  '\\nYour Pro activation code will be removed from this site. Pro add-ons will be unavailable until you upgrade again. Your forms, entries and settings will not be deleted.\\n' => 'Ваш код активации Pro будет удален с этого сайта. Дополнения Pro будут недоступны, пока вы не обновите их снова. Ваши формы, записи и настройки не будут удалены.',
  '\\nSwitch to Free?\\n' => 'Перейти на бесплатную версию?',
  '\\nAdvanced features and advanced fields used in your forms will be disabled. Your forms, entries and settings will not be deleted, and will be available again if you upgrade.\\n' => 'Расширенные функции и дополнительные поля, используемые в ваших формах, будут отключены. Ваши формы, записи и настройки не будут удалены и снова станут доступны после обновления.',
  '\\nYour Pro activation code will be removed from this site. Advanced features, Pro fields and add-ons will be unavailable until you upgrade again. Your forms, entries and settings will not be deleted.\\n' => 'Ваш код активации Pro будет удален с этого сайта. Расширенные функции, поля Pro и надстройки будут недоступны, пока вы не обновитесь снова. Ваши формы, записи и настройки не будут удалены.',
  '\\nKeepPro\\n' => 'KeepPro',
  '[[\'Keep Free Plus\\n' => 'Keep Free Plus',
  '\\nSwitch to Free Plus\', \'en\']]' => 'Перейти на Free Plus',
  '\\nSwitch to Free\\n' => 'Перейти на бесплатную версию',
  '\\nPlan change\\n' => 'Изменение плана',
  '\\nYour data stays untouched; only access to the features is limited.\\n' => 'Ваши данные остаются нетронутыми; ограничен только доступ к функциям.',
  '[[\'An error occurred. Please try again.\\n' => 'Произошла ошибка. Пожалуйста, попробуйте еще раз.',
  '\\nUnable to change the plan. Please try again.\\n' => 'Невозможно изменить план. Пожалуйста, попробуйте еще раз.',
  '\\nPlan selected\\n' => 'План выбран',
  '\\nSet up form notifications\\n' => 'Настройте уведомления формы',
  '\\nCheck whether your server can send emails, so you know you will receive form notifications.\\n' => 'Проверьте, может ли ваш сервер отправлять электронную почту, чтобы вы знали, что будете получать уведомления в форме.',
  '\\nForm notification email\\n' => 'Форма уведомления по электронной почте',
  '\\nThis is saved in General Settings and can be changed later.\\n' => 'Это сохраняется в общих настройках и может быть изменено позже.',
  '\\nYour default settings\\n' => 'Ваши настройки по умолчанию',
  '\\nNotifications stay off until delivery is verified\\n' => 'Уведомления отключены до тех пор, пока не будет подтверждена доставка',
  'Sender' => 'Отправитель',
  '\\nYour forms and submissions are ready to use\\n' => 'Ваши формы и материалы готовы к использованию',
  '\\nSave and test email delivery", \'en\']]' => 'Сохраните и проверьте доставку электронной почты',
  '[[\'Checking email delivery...\\n' => 'Проверка доставки электронной почты...',
  '\\nA test email was sent. Waiting for delivery confirmation...\\n' => 'Отправлено тестовое письмо. Ожидание подтверждения доставки...',
  '\\nEmail delivery is ready. Form notifications can be sent.\\n' => 'Доставка по электронной почте готова. Уведомления в форме можно отправлять.',
  '\\nYour test email was sent, but delivery is not confirmed yet. Check the inbox or spam folder for the address below; you can finish setup and try again later from General Settings.\\n' => 'Ваше тестовое письмо было отправлено, но доставка еще не подтверждена. Проверьте папку «Входящие» или «Спам» на наличие адреса, указанного ниже; вы можете завершить настройку и повторить попытку позже в разделе «Общие настройки».',
  '[[\'We could not verify delivery. Your email address was saved; please check your mail configuration in General Settings.\\n' => 'Нам не удалось проверить доставку. Ваш адрес электронной почты был сохранен; пожалуйста, проверьте конфигурацию вашей почты в общих настройках.',
  '\\nYour test email was delivered, but its deliverability score is only%1$sout of 100 (below%2$s). The emails your forms send will most likely be filtered as spam. Set up SMTP and run the check again.\\n' => 'Ваше тестовое письмо было доставлено, но его показатель доставляемости составляет всего%1$sиз 100 (ниже%2$s). Письма, отправляемые вашими формами, скорее всего, будут отфильтрованы как спам. Настройте SMTP и запустите проверку еще раз.',
  '\\nFinish setup\\n' => 'Завершить настройку',
  '\\nselected\\n' => 'выбрано',
