  '[["This field is currently unavailable. Please contact the site administrator.\\n' => 'Это поле в настоящее время недоступно. Пожалуйста, свяжитесь с администратором сайта.',
  '\\nWould you like to customize the form using the colors of the active template?\\n' => 'Хотите настроить форму, используя цвета активного шаблона?',
  '\\nFlux Forms has utilized the colors of the active template. Please choose a color for each option below to customize the form you are creating based on the colors of your template. By selecting a color for each option below, the color of all form fields associated with that feature will change accordingly.\', \'en\']]' => 'Flux Forms использовал цвета активного шаблона. Пожалуйста, выберите цвет для каждого варианта ниже, чтобы настроить форму, которую вы создаете, на основе цветов вашего шаблона. При выборе цвета для каждого параметра ниже цвет всех полей формы, связанных с этой функцией, изменится соответствующим образом.',
  '\\nButtons text colors\\n' => 'Цвета текста кнопок',
