  '\\nUpload the%sfile\\n' => 'Загрузите файл%s',
  'CSV' => 'CSV-файл',
  '\\nDataset\\n' => 'Набор данных',
  '[[\'The%shas been successfully completed\\n' => '%sуспешно завершен',
