  '\\ninstallation\\n' => 'установка',
  '\\nThe%shave been deleted.\\n' => '%sудален.',
  '\\nThe%sfield must be correctly filled out to proceed.\', \'en\']]' => 'Для продолжения поле%sдолжно быть правильно заполнено.',
  '\\nSubmitted Form\\n' => 'Отправленная форма',
  '\\nYou can\'t add reCAPTCHA to payment forms.\\n' => 'Вы не можете добавить reCAPTCHA в формы оплаты.',
  '\\nLearn more about%sor watch the video tutorial.\\n' => 'Узнайте больше о%sили посмотрите видеоруководство.',
  '\\nLearn more%s\\n' => 'Подробнее%s',
  '\\nGoogle reCAPTCHA\\n' => 'Google reCAPTCHA',
  '\\nThe connection was interrupted, but don\\\'t worry—your edits are safely stored in your browser. Refresh the page to continue working.\\n' => 'Соединение было прервано, но не волнуйтесь: ваши изменения надежно хранятся в вашем браузере. Обновите страницу, чтобы продолжить работу.',
  '[["There is an auto-saved version of the form available. Do you want to restore it?\\n' => 'Доступна автоматически сохраняемая версия формы. Хотите восстановить ее?',
  '\\nSMS notification could not be sent. Check if the SMS plugin is installed and configured properly.\\n' => 'Не удалось отправить SMS-уведомление. Проверьте, правильно ли установлен и настроен плагин SMS.',
  '\\nYour request was completed successfully.%1$s%2$s\\n' => 'Ваш запрос успешно выполнен.%1$s%2$s',
  '\\nPayPal\\n' => 'PayPal',
  '\\nTo use%1$sfeatures in your forms, you need to get your%2$skeys.\\n' => 'Чтобы использовать функции%1$sв своих формах, вам необходимо получить ключи%2$s.',
  '\\nGo to the add-ons page in the Flux Forms plugin, install the%sadd-on, and try again.\\n' => 'Перейдите на страницу надстроек в плагине Flux Forms, установите надстройку%sи повторите попытку.',
  '\\nTo create a payment form to collect online payments, install a payment add-on such as the%sAdd-on first.\\n' => 'Чтобы создать платежную форму для сбора онлайн-платежей, сначала установите надстройку для оплаты, например надстройку%s.',
  'Activated' => 'Активировано',
  '\\nThank\\n' => 'Спасибо',
  '\\nThe%splugin may interfere with Flux Forms form functionality. If you encounter any issues with the forms, disable caching for the Flux Forms plugin in the%ssettings.\\n' => 'Плагин%sможет мешать работе форм Flux Forms. Если у вас возникли проблемы с формами, отключите кеширование для плагина Flux Forms в настройках%s.',
  '\\nRemind me later\\n' => 'Напомни мне позже',
  '[["Got it, don\'t show it again\\n' => 'Понятно, больше не показывать',
  '\\nThe value of the%1$sfield does not match the pattern and must be at least%2$scharacters.\\n' => 'Значение поля%1$sне соответствует шаблону и должно содержать не менее символов%2$s.',
  '\\nThe value of the%1$sfield does not match the pattern and must be at most%2$scharacters.\\n' => 'Значение поля%1$sне соответствует шаблону и должно содержать не более символов%2$s.',
  '[[\'Please enter valid value for the%sfield.\\n' => 'Пожалуйста, введите допустимое значение в поле%s.',
  '\\n%slist\\n' => ' Список%s',
  '\\nThe uploaded file exceeds the allowable limit of%sMB.\\n' => 'Загруженный файл превышает допустимый лимит%sМБ.',
  '\\nThe uploaded file is below the required minimum size of%sMB.\\n' => 'Размер загруженного файла меньше требуемого минимального размера%sМБ.',
  '\\nReview the entered values in the%stab. This message appeared because an error was detected.\\n' => 'Проверьте введенные значения на вкладке%s. Это сообщение появилось, потому что была обнаружена ошибка.',
  '\\nAre you sure you want to duplicate the "%s" ?\\n' => 'Вы уверены, что хотите дублировать «%s»?',
  '\\nWe are sorry, the booking time for the%soption has expired. Please choose from the other available options.\\n' => 'К сожалению, время бронирования опции%sистекло. Пожалуйста, выберите один из других доступных вариантов.',
  '\\nWe are sorry, the%soption is currently at full capacity. Please choose from the other available options.\\n' => 'Приносим извинения, опция%sв настоящее время загружена на полную мощность. Пожалуйста, выберите один из других доступных вариантов.',
  '\\n%sPayment Add-on\\n' => '%sПлатежное дополнение',
  '\\nThe%sadd-on for Flux Forms enables you to integrate your WordPress site with%sfor payment processing, donations, and online orders.\\n' => 'Дополнение%sдля Flux Forms позволяет интегрировать ваш сайт WordPress с%sдля обработки платежей, пожертвований и онлайн-заказов.',
  '\\nActivation Code\\n' => 'Код активации',
  '\\nWant to use this feature? It is included in Free Plus and Pro plans.\\n' => 'Хотите использовать эту функцию? Он включен в планы Free Plus и Pro.',
  '\\nFree Plus Guide\\n' => 'Бесплатное руководство Plus',
