  '\\nEvery feature, with no limits, and support included.\\n' => 'Все функции без ограничений и поддержка включены.',
  '\\nSearch Results\\n' => 'Результаты поиска',
  '\\nFound%s%sfor: "%s"\\n' => 'Найдено%s%sдля: "%s"',
  'result' => 'результат',
  '\\nresults\\n' => 'результаты',
  '\\nNo results found for:\', \'en\']]' => 'По запросу:\', \'en\']] результатов не найдено',
  '\\nFound%1$s%2$sfor\\n' => 'Найдено%1$s%2$sдля',
  '\\nSession Duration\\n' => 'Продолжительность сеанса',
  '\\nSet how long form security tokens remain valid. Longer durations provide better user experience but may reduce security.\\n' => 'Установите, как долго токены безопасности формы остаются действительными. Более длительная продолжительность обеспечивает лучший пользовательский опыт, но может снизить безопасность.',
