  '\\nCustom\\n' => 'Пользовательский',
  'Website' => 'Веб-сайт',
  '\\nLink all sides\\n' => 'Свяжите все стороны',
  '\\nForm Title\\n' => 'Заголовок формы',
  '\\nYour text here...\\n' => 'Ваш текст здесь...',
  '\\nVisit Website\\n' => 'Посетить веб-сайт',
  '\\nLeft column content\\n' => 'Содержимое левого столбца',
  '\\nRight column content\\n' => 'Содержимое правого столбца',
  '\\nSent by shortcode_website_name\\n' => 'Отправлено пользователем shortcode_website_name',
  '\\nCustom HTML content\\n' => 'Пользовательский HTML-контент',
  '\\nJohn Doe\\n' => 'Джон Доу',
  '\\nThis is a sample form submission.\\n' => 'Это образец отправки формы.',
  '\\nMy Website\\n' => 'Мой сайт',
  'Bold' => 'Жирный',
  'Italic' => 'Курсив',
  'Underline' => 'Подчеркнуть',
  'Clear formatting' => 'Очистить форматирование',
  '\\nToggle navigation\\n' => 'Переключить навигацию',
  '\\nView toggle\\n' => 'Переключение просмотра',
  '\\nLocate Me\\n' => 'Найди меня',
  '\\nError fetching address\\n' => 'Ошибка получения адреса',
  '\\nGeolocation is not supported by this browser.\\n' => 'Геолокация не поддерживается этим браузером.',
  '\\nverify\\n' => 'проверить',
  'Failed' => 'Не удалось',
  '\\nThe form cannot be submitted because it requires a payment method, which is currently missing. If you are the Admin, please add a payment method to the form or change the form type to "Form" or "Survey".\\n' => 'Невозможно отправить форму, поскольку для нее требуется способ оплаты, который в настоящее время отсутствует. Если вы являетесь администратором, добавьте в форму способ оплаты или измените тип формы на «Форма» или «Опрос».',
  'Payments' => 'Платежи',
  '\\nCache Plugin Detected\\n' => 'Обнаружен плагин кэша',
  '\\nThe following cache plugins may interfere with form functionality. If you experience issues, please review the documentation.\\n' => 'Следующие плагины кэша могут мешать работе формы. Если у вас возникли проблемы, просмотрите документацию.',
  'Plugin' => 'Плагин',
  'Version' => 'Версия',
  '\\nRead more about cache compatibility\\n' => 'Подробнее о совместимости кэша',
  'Dismiss' => 'Уволить',
  '\\nDismiss All\\n' => 'Отклонить все',
  '\\nDismiss%s\\n' => 'Отклонить%s',
  '\\nSecurity Plugin Detected\\n' => 'Обнаружен плагин безопасности',
  '\\nThe following security plugin may block form submissions with 403 errors. It may block the REST API, remove the X-WP-Nonce header, or apply firewall rules to form requests.\\n' => 'Следующий плагин безопасности может блокировать отправку форм с ошибкой 403. Он может заблокировать REST API, удалить заголовок X-WP-Nonce или применить правила брандмауэра для формирования запросов.',
  '\\nRead more about security plugin compatibility\\n' => 'Подробнее о совместимости плагинов безопасности',
  '\\nAuto-Populate Add-on\\n' => 'Автозаполнение дополнения',
  '\\nThe Auto-Populate add-on enables you to automatically populate form fields from datasets, previously submitted forms, or external APIs.\\n' => 'Дополнение «Автозаполнение» позволяет автоматически заполнять поля форм из наборов данных, ранее отправленных форм или внешних API.',
  '\\nForm Security & Spam Protection\\n' => 'Безопасность форм и защита от спама',
  '\\nBehavior-based anti-spam and API abuse protection with rate limits and a stop-loss for paid notifications such as SMS, Telegram, email and webhooks.\\n' => 'Защита от спама на основе поведения и защита от злоупотреблений API с ограничениями скорости и стоп-лоссом для платных уведомлений, таких как SMS, Telegram, электронная почта и веб-перехватчики.',
  '\\nGoogle Sheet Add-on\\n' => 'Дополнение Google Таблиц',
  '\\nAutomatically send form submissions to your Google Sheets in real time. Connect a service account, map fields to columns, and keep a live, styled spreadsheet of every response — no webhook or browser login required.\\n' => 'Автоматически отправляйте отправленные формы в Google Таблицы в режиме реального времени. Подключите сервисный аккаунт, сопоставьте поля со столбцами и сохраняйте действующую стилизованную электронную таблицу каждого ответа — вебхук или вход в браузер не требуется.',
  '\\nPlease fill in all required fields\\n' => 'Пожалуйста, заполните все обязательные поля',
  '\\nEmail Server Status\\n' => 'Состояние почтового сервера',
  '\\nThe test email never arrived\\n' => 'Тестовое письмо так и не пришло',
  '\\nYour WordPress site cannot send emails reliably. This is a very common hosting issue — the default PHP mail function is often blocked or ends up in spam. Installing an SMTP plugin routes your emails through a verified mail service and fixes this in minutes.\\n' => 'Ваш сайт WordPress не может надежно отправлять электронные письма. Это очень распространенная проблема с хостингом — функция почты PHP по умолчанию часто блокируется или попадает в спам. Установка плагина SMTP направляет вашу электронную почту через проверенную почтовую службу и устраняет проблему за считанные минуты.',
  '\\nWordPress sent the email - it just never arrived\\n' => 'WordPress отправил электронное письмо, но оно так и не пришло',
  '\\nYour site handed the message to your mail server successfully, so WordPress and this plugin did their part. It was lost, delayed or rejected afterwards - most often the receiving mailbox filed it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.\\n' => 'Ваш сайт успешно передал сообщение на ваш почтовый сервер, поэтому WordPress и этот плагин внесли свой вклад. Впоследствии оно было потеряно, задержано или отклонено — чаще всего получающий почтовый ящик считал его спамом, или ваш хост не доставлял его из исходящей очереди. Это решается отправкой через службу SMTP с записями SPF и DKIM для вашего домена.',
  '\\nWordPress could not send the email\\n' => 'WordPress не удалось отправить электронное письмо',
  '\\nThe message never left your website: WordPress returned an error while sending it. Install and configure an SMTP plugin, or ask your host whether PHP mail is disabled.\\n' => 'Сообщение так и не покинуло ваш сайт: WordPress вернул ошибку при отправке. Установите и настройте плагин SMTP или спросите у своего хостера, отключена ли почта PHP.',
  '\\nYour emails arrive, but will most likely land in spam\\n' => 'Ваши письма доходят, но, скорее всего, попадут в спам',
  '[[\'Delivery itself works - the test message reached us. What is missing is trust: sending through an SMTP service and adding SPF and DKIM records for your domain is what moves your emails from the spam folder to the inbox.\\n' => 'Сама доставка работает - до нас дошло тестовое сообщение. Чего не хватает, так это доверия: отправка через службу SMTP и добавление записей SPF и DKIM для вашего домена — вот что перемещает ваши электронные письма из папки со спамом в папку «Входящие».',
  '\\nThe test email was delivered with a deliverability score of%1$sout of 100. Under%2$s, most mailboxes file messages in the spam folder, so the people filling in your forms may never see them.\\n' => 'Тестовое электронное письмо было доставлено с оценкой доставляемости%1$sиз 100. При использовании%2$sбольшинство почтовых ящиков отправляют сообщения в папку «Спам», поэтому люди, заполняющие ваши формы, могут их никогда не увидеть.',
  '\\nStep-by-step SMTP setup guide\\n' => 'Пошаговое руководство по настройке SMTP',
  '\\nYour email server is working. A detailed HTML report has been sent to%s.\\n' => 'Ваш почтовый сервер работает. Подробный отчет в формате HTML отправлен на адрес%s.',
  '\\nyour admin email address\\n' => '\\ваш адрес электронной почты администратора',
  '\\nSpam Score Report on the Way!\\n' => 'Отчет о спаме уже в пути!',
  '\\nA complete email health report — including your spam score, deliverability details, and recommendations — will be sent to%swithin the next few minutes.\\n' => 'Полный отчет о состоянии электронной почты, включая оценку спама, сведения о доставляемости и рекомендации, будет отправлен на адрес%sв течение следующих нескольких минут.',
  '\\nEmail notifications may not be delivered\\n' => 'Уведомления по электронной почте могут не доставляться',
  '\\nThis form\'s email notification feature is enabled, but email delivery has not been verified and the latest spam score is%s/100. The form was saved, but admin notification emails may not reach you until SMTP/email delivery is fixed.\\n' => 'Функция уведомления по электронной почте в этой форме включена, но доставка электронной почты не проверена, а последняя оценка спама —%s/100. Форма была сохранена, но электронные письма с уведомлениями администратора могут не дойти до вас, пока доставка SMTP/электронной почты не будет исправлена.',
  '\\nNotification emails are turned off\\n' => 'Уведомления по электронной почте отключены',
  '\\nFlux Forms will not send any email — neither to you nor to the person who submits this form — until "This site can send emails" is enabled in Email Settings.\\n' => 'Flux Forms не будет отправлять электронные письма — ни вам, ни лицу, отправившему эту форму, — до тех пор, пока в настройках электронной почты не будет включен параметр «Этот сайт может отправлять электронные письма».',
  '[[\'Enable email sending\\n' => 'Включить отправку электронной почты',
  '\\nClick "Check Email Server" to test delivery, turn this switch on, then press Save.\\n' => 'Нажмите «Проверить сервер электронной почты», чтобы проверить доставку, включите этот переключатель, затем нажмите «Сохранить».',
  '\\nDelivery is taking longer than expected\', \'en\']]' => 'Доставка занимает больше времени, чем ожидалось',
  '\\nWordPress sent the test email, but our server has not received it yet. This may be a temporary delay. Check the diagnostics below to troubleshoot.\\n' => 'WordPress отправил тестовое письмо, но наш сервер еще не получил его. Это может быть временная задержка. Чтобы устранить неполадки, проверьте приведенную ниже диагностику.',
  '\\nPrepare Test\\n' => 'Подготовка теста',
  '\\nConnecting to WhiteStudio to generate a unique test email address.\\n' => 'Подключение к WhiteStudio для создания уникального тестового адреса электронной почты.',
  '\\nWordPress Sends the Email\\n' => 'WordPress отправляет электронное письмо',
  '\\nWordPress hands a real message to your mail server. A tick here means WordPress sent it, not yet that it arrived.\\n' => 'WordPress передает на ваш почтовый сервер настоящее сообщение. Галочка здесь означает, что WordPress отправил его, но он еще не прибыл.',
  '\\nWaiting for Delivery\\n' => 'Ожидание доставки',
  '\\nChecking whether the test email arrived at our server (usually takes a few seconds).\\n' => 'Проверка того, пришло ли тестовое письмо на наш сервер (обычно занимает несколько секунд).',
  '\\nQuick Result\\n' => 'Быстрый результат',
  '\\nShowing the first delivery result — you will see right away if email is working.\\n' => 'Показываем первый результат доставки — вы сразу увидите, работает ли электронная почта.',
  '\\nFull Report\\n' => 'Полный отчет',
  '\\nA detailed HTML report with full diagnostics is being prepared and emailed to you.\\n' => 'Подготовленный отчет в формате HTML с полной диагностикой будет отправлен вам по электронной почте.',
  'Running' => 'Бег',
  'Finished' => 'Закончено',
  '\\nNeeds attention\\n' => 'Требует внимания',
  '\\n%sof 5 steps done\\n' => '%sиз 5 шагов выполнено',
  '\\nStep%sof 5\\n' => 'Шаг%sиз 5',
  '\\n/ 100\\n' => '/ 100',
  '\\nTest started\\n' => 'Тест начался',
  '[[\'A unique address is being generated for this test.\\n' => 'Для этого теста создается уникальный адрес.',
  '\\nWaiting for the email to arrive\\n' => 'Ожидание прибытия письма',
  '\\nWe check our server every few seconds. Please keep this page open.\\n' => 'Мы проверяем наш сервер каждые несколько секунд. Пожалуйста, оставьте эту страницу открытой.',
  '\\nYour email server is healthy\\n' => 'Ваш почтовый сервер исправен',
  '\\nThe test email arrived, and the subject and unique-code checks both passed.\\n' => 'Тестовое письмо пришло, и проверка темы и уникального кода прошла успешно.',
  '\\nDelivered, but likely to be filtered as spam\\n' => 'Доставлено, но, вероятно, будет отфильтровано как спам',
  '\\nDelivered, but deliverability is weak\\n' => 'Доставлено, но доставляемость низкая',
  '\\nNo email arrived\\n' => 'Письмо не пришло',
  '\\nNothing was received during the test window, so your server most likely cannot send email.\\n' => 'Во время тестового окна ничего не было получено, поэтому ваш сервер, скорее всего, не может отправлять электронную почту.',
  '\\nThe test timed out\\n' => 'Тайм-аут теста истек',
  '\\nThe test reached its time limit. Your server may be slow, or may block outbound email.\\n' => 'Испытание достигло лимита времени. Ваш сервер может работать медленно или блокировать исходящую электронную почту.',
  '\\nThe test email could not be sent\\n' => 'Не удалось отправить тестовое письмо',
  '\\nWordPress returned an error while sending. See the message below.\\n' => 'WordPress возвратил ошибку при отправке. См. сообщение ниже.',
  '\\nThe connection was lost\', \'en\']]' => 'Соединение потеряно',
  '\\nNo answer came back from the server. Refresh the page and try again.\\n' => 'От сервера не получен ответ. Обновите страницу и повторите попытку.',
  '\\nThis test needs a higher plan\\n' => 'Этот тест требует более высокого плана',
  '\\nUpgrade your plan to run the full delivery test.\\n' => 'Обновите свой план, чтобы провести полную проверку доставки.',
  '\\nYour email server is working. A detailed HTML report has been sent to\\n' => 'Ваш почтовый сервер работает. Подробный отчет в формате HTML отправлен на адрес',
  '\\nA complete email health report — including your spam score, deliverability details, and recommendations — will be sent within the next few minutes to\\n' => 'Полный отчет о состоянии электронной почты, включая оценку спама, сведения о доставляемости и рекомендации, будет отправлен в течение следующих нескольких минут на адрес',
  '\\nUpgrade required\\n' => 'Требуется обновление',
