  'Refunded' => 'Возвращено',
  'Partly refunded' => 'Частично возмещено',
  '\\nSorry, you are not allowed to access this page.\\n' => 'К сожалению, у вас нет доступа к этой странице.',
  '\\nPayments taken through your forms, from every payment provider. API keys and the active provider are set on the plugin Settings page, Payment tab.\\n' => 'Платежи, принимаемые через ваши формы от каждого поставщика платежей. Ключи API и активный провайдер задаются на странице настроек плагина, вкладка «Оплата».',
  'Settings saved.' => 'Настройки сохранены.',
  '\\nA Stripe webhook signing secret starts with "whsec_".\\n' => 'Секрет подписи вебхука Stripe начинается с «whsec_».',
