  '\\nSubscription\\n' => 'Подписка',
  '[[\'One-time\\n' => 'Одноразовый',
  '\\nThe latest%dpayments are shown.\\n' => 'Отображаются последние платежи%d.',
  '\\nTest provider (development only)\\n' => 'Поставщик тестов (только для разработки)',
  '[[\'Test outcome\\n' => 'Результат теста',
  '\\nApprove every payment\\n' => 'Подтвердить каждый платеж',
  '\\nDecline every payment\\n' => 'Отклонять каждый платеж',
  '\\nNo money is taken. Development only.\\n' => 'Деньги не берутся. Только разработка.',
  '\\nTEST MODE: no card is charged.\\n' => 'ТЕСТОВЫЙ РЕЖИМ: оплата с карты не взимается.',
  '\\nTest provider: the payment was declined.\\n' => 'Провайдер тестирования: платеж отклонен.',
  '[[\'Publishable key\\n' => 'Публикуемый ключ',
  'Secret key' => 'Секретный ключ',
  '\\nStripe is not configured on this site. Please contact the site administrator.\\n' => 'Stripe не настроен на этом сайте. Пожалуйста, свяжитесь с администратором сайта.',
  '\\nThe payment method of this form is not supported.\\n' => 'Способ оплаты, указанный в этой форме, не поддерживается.',
  '\\nThe payment could not be started. Please try again.\\n' => 'Не удалось начать платеж. Пожалуйста, попробуйте еще раз.',
  '\\nOptional but recommended: in the Stripe Dashboard add a webhook endpoint with this URL and the events payment_intent.succeeded, payment_intent.payment_failed, payment_intent.canceled, charge.refunded, customer.subscription.updated and customer.subscription.deleted, then paste its signing secret below.\\n' => 'Необязательно, но рекомендуется: на панели управления Stripe добавьте конечную точку веб-перехватчика с этим URL-адресом и событиями pay_intent.succeeded, pay_intent.pay_failed, pay_intent.canceled, charge.refunded, customer.subscription.updated и customer.subscription.deleted, а затем вставьте секрет подписи ниже.',
  '\\nWebhook signing secret\\n' => 'Секрет подписи вебхука',
  '\\nSaved - leave empty to keep it\\n' => 'Сохранено: оставьте пустым, чтобы сохранить его.',
  '\\nRemove the saved secret\\n' => 'Удалить сохраненный секрет',
  '\\nInvalid or expired nonce\\n' => 'Неверный или просроченный одноразовый номер',
  '\\nNo payment provider is available on this site. Please contact the site administrator.\\n' => 'На этом сайте нет платежных систем. Пожалуйста, свяжитесь с администратором сайта.',
  '\\nToo many payment attempts. Please wait a few minutes and try again.\\n' => 'Слишком много попыток оплаты. Пожалуйста, подождите несколько минут и повторите попытку.',
  '\\nInvalid payment data. Please refresh the page and try again.\\n' => 'Неверные данные платежа. Пожалуйста, обновите страницу и повторите попытку.',
  '\\nThe payment provider is not configured on this site. Please contact the site administrator.\\n' => 'Поставщик платежей не настроен на этом сайте. Пожалуйста, свяжитесь с администратором сайта.',
  '\\nNo payment amount detected. Please review your selected items and try again. If the problem persists, contact support.\\n' => 'Сумма платежа не обнаружена. Пожалуйста, проверьте выбранные элементы и повторите попытку. Если проблема не устранена, обратитесь в службу поддержки.',
  '\\nToo many requests. Please wait a moment and try again.\\n' => 'Слишком много запросов. Пожалуйста, подождите немного и повторите попытку.',
  '\\nPayment not found.\\n' => 'Платеж не найден.',
  '\\nYour payment has not been confirmed yet. Please wait a moment and try again. If the problem persists, contact the site administrator.\\n' => 'Ваш платеж еще не подтвержден. Пожалуйста, подождите немного и повторите попытку. Если проблема не устранена, обратитесь к администратору сайта.',
  '\\nOnline payment is not available at the moment. Please try again later or contact us.\\n' => 'Онлайн-оплата в данный момент недоступна. Пожалуйста, повторите попытку позже или свяжитесь с нами.',
  '\\nActive payment provider\\n' => 'Активный поставщик платежей',
  '\\nPayment forms take card payments through this provider. Only installed providers are listed.\\n' => 'Платежные формы принимают платежи по картам через этого провайдера. В списке указаны только установленные поставщики.',
  '\\nSaved — leave empty to keep\\n' => 'Сохранено — оставьте пустым, чтобы сохранить',
  '\\n%ssettings\\n' => ' Настройки%s',
  '\\nFlux Forms replaces%s, which has been deactivated. Your forms, entries and settings stay in place. You can delete the old plugin.\\n' => 'Flux Forms заменяет%s, который был деактивирован. Ваши формы, записи и настройки останутся на месте. Вы можете удалить старый плагин.',
  '\\nUpdating amount...\\n' => 'Обновление суммы...',
  '\\nThe amount could not be verified. Please check your selections and try again.\\n' => 'Не удалось проверить сумму. Пожалуйста, проверьте свой выбор и повторите попытку.',
  '\\nSubject made by Flux Forms (with the tracking code)\\n' => 'Тема, созданная Flux Forms (с кодом отслеживания)',
  '\\nMessage: tracking code and submitted values (HTML)\\n' => 'Сообщение: код отслеживания и отправленные значения (HTML)',
  '\\nLink to the message / response page\\n' => 'Ссылка на страницу сообщения/ответа',
  '\\nUser name (registration, password recovery)\\n' => 'Имя пользователя (регистрация, восстановление пароля)',
  '\\nWe have received your message\\n' => 'Мы получили ваше сообщение',
  '\\nNew form message\\n' => 'Новое сообщение формы',
  '\\nSent to the form\\\'s notification addresses when a form is filled in or a message gets a new reply.\\n' => 'Отправляется на адреса уведомлений формы, когда форма заполнена или на сообщение получен новый ответ.',
  '\\nNew message\\n' => 'Новое сообщение',
