  '[[\'%dautomation is on.\', \'en\']]' . chr(0) . '[[\'%dautomations are on.\', \'en\']]' => ' Автоматизация%dвключена.' . chr(0) . ' Автоматизация%dвключена.' . chr(0) . ' Автоматизация%dвключена.',
