  '\\nThe security service is not available right now. Your form still works.\\n' => 'Служба безопасности в данный момент недоступна. Ваша форма все еще работает.',
  '\\nPlease refresh the form and try again.\\n' => 'Обновите форму и повторите попытку.',
  '\\nToo many requests. Please try again shortly.\\n' => 'Слишком много запросов. Пожалуйста, повторите попытку через некоторое время.',
  '[[\'Missing challenge.\\n' => 'Отсутствует вызов.',
  '\\nExpired challenge.\\n' => 'Просроченный вызов.',
  '\\nChallenge already used.\\n' => 'Вызов уже использован.',
  '\\nForm mismatch.\\n' => 'Несоответствие формы.',
  '\\nThe security service is temporarily unavailable.\\n' => 'Служба безопасности временно недоступна.',
  '\\nThe form was open for too long or could not be verified. Please refresh the page and submit again.\\n' => 'Форма была открыта слишком долго или не могла быть проверена. Пожалуйста, обновите страницу и отправьте заявку еще раз.',
  '\\nYour request looked too fast or unusual. Please try again in a few minutes.\\n' => 'Ваш запрос выглядел слишком быстрым или необычным. Пожалуйста, повторите попытку через несколько минут.',
