  '\\nSubmit score\\n' => 'Отправить оценку',
  '\\nPaid notification score\', \'en\']]' => 'Оценка платных уведомлений',
  '\\nToken TTL\\n' => 'Срок жизни токена',
  '\\nIP submit/min\\n' => 'IP-отправка/мин',
  '\\nResponse add/min\\n' => 'Добавление ответа/мин',
  '\\nRequest protection\\n' => 'Запросить защиту',
  '\\nControls that run before EFB REST callbacks.\\n' => 'Элементы управления, которые выполняются перед обратными вызовами EFB REST.',
  '\\nEnable Human Shield\\n' => 'Включить «Живой щит»',
  '\\nActivate behavior tokens and rate limits.\\n' => 'Активируйте жетоны поведения и ограничения скорости.',
  '\\nMonitor logs only; soft block is recommended for production rollout.\\n' => 'Отслеживать только журналы; для производственного развертывания рекомендуется мягкий блок.',
  '\\nMinimum submit score\\n' => 'Минимальный балл за отправку',
