  '\\nRoute\\n' => 'Маршрут',
  'Decision' => 'Решение',
  '[[\'Score\\n' => 'Оценка',
  '\\nReasons\\n' => 'Причины',
  '\\nSystem readiness\\n' => 'Готовность системы',
  '\\nHuman Shield checks these functions before enforcing security rules.\\n' => 'Human Shield проверяет эти функции перед применением правил безопасности.',
  '\\nPHP requirements are ready.\\n' => 'Требования PHP готовы.',
  '\\nSome required PHP functions are unavailable.", \'en\']]' => 'Некоторые необходимые функции PHP недоступны.',
