  '\\nFollow these steps to set up auto-populate for your forms\\n' => 'Выполните следующие действия, чтобы настроить автоматическое заполнение форм.',
  '\\nQuick Start Guide\\n' => 'Краткое руководство',
  '\\nTips & Notes\\n' => 'Советы и примечания',
  '\\nEditing Data\\n' => 'Редактирование данных',
  '\\nSupported format: CSV with UTF-8 encoding.\\n' => 'Поддерживаемый формат: CSV с кодировкой UTF-8.',
  '\\nForm Builder Tips\\n' => 'Советы по созданию форм',
  '[[\'Use conditions to filter dataset rows based on user input.\\n' => 'Используйте условия для фильтрации строк набора данных на основе пользовательского ввода.',
