  '\\nClick "Add API Connection" to create a new connection and enter your API endpoint URL.\\n' => 'Нажмите «Добавить соединение API», чтобы создать новое соединение, и введите URL-адрес конечной точки API.',
  '\\nAdd Connection\\n' => 'Добавить соединение',
  '\\nConfigure authentication (API Key, Bearer Token, or Basic Auth) if your API requires it.\\n' => 'Настройте аутентификацию (ключ API, токен носителя или базовую аутентификацию), если этого требует ваш API.',
  'Authentication' => 'Аутентификация',
  '\\nSelect a form and map API response fields to your form fields for auto-populate.\\n' => 'Выберите форму и сопоставьте поля ответа API с полями формы для автоматического заполнения.',
  '\\nUse the Test button to verify the API returns expected data, then save your connection.\\n' => 'Используйте кнопку «Тест», чтобы убедиться, что API возвращает ожидаемые данные, затем сохраните соединение.',
  '\\nTest & Save\\n' => 'Проверить и сохранить',
  '\\nUse cache settings to reduce API calls and improve performance.\', \'en\']]' => 'Используйте настройки кэша, чтобы уменьшить количество вызовов API и повысить производительность.',
