  '\\nWhiteStudio.team\\n' => 'WhiteStudio.team',
  '\\nEFB\\n' => 'EFB',
  '[[\'Flux Forms is a free and powerful WordPress form builder plugin for creating contact forms, payment forms, surveys, registration forms, multi-step forms, file upload forms, electronic signature forms, and audio, video, and screen recording forms, with conditional logic, email notifications, integrations, entry management, and advanced spam protection.\\n' => 'Flux Forms — это бесплатный и мощный плагин для создания форм WordPress для создания контактных форм, форм оплаты, опросов, форм регистрации, многошаговых форм, форм загрузки файлов, форм электронной подписи, а также форм аудио, видео и записи экрана с условной логикой, уведомлениями по электронной почте, интеграцией, управлением записями и расширенной защитой от спама.',
  '\\nWordPress Form Builder Plugin\\n' => 'Плагин WordPress Form Builder',
