  '\\nSome plugin files are missing, so the plugin stopped loading to keep your site running. Please reinstall Flux Forms from the Plugins page — your forms, messages, and settings are kept.\\n' => 'Некоторые файлы плагина отсутствуют, поэтому плагин перестал загружаться, чтобы ваш сайт продолжал работать. Пожалуйста, переустановите Flux Forms со страницы Плагины — ваши формы, сообщения и настройки сохранятся.',
