  'Submit' => 'Отправить',
  'Purchase Order' => 'Заказ на покупку',
  'It is not possible to include reCAPTCHA on payment forms.' => 'Невозможно включить reCAPTCHA в формы оплаты.',
  'This site can send emails' => 'Этот сайт может отправлять электронные письма',
  'Weekly email health and form activity report' => 'Еженедельный отчет о состоянии электронной почты и активности форм',
  'Adds your form activity totals &ndash; forms, views and submissions &ndash; to the weekly email your site sends the main administrator. These totals are read on your own site and are never sent to WhiteStudio.' => 'Добавляет общие сведения о вашей активности в форме (формы, просмотры и отправки) в еженедельное электронное письмо, которое ваш сайт отправляет главному администратору. Эти итоговые данные считываются на вашем сайте и никогда не отправляются в WhiteStudio.',
  'No automated email check has run yet.' => 'Автоматическая проверка электронной почты пока не выполнялась.',
  'Collect email delivery statistics' => 'Сбор статистики доставки электронной почты',
  'Counts how many emails were sent or failed, shows them in the dashboard widget, and adds the email delivery status section to the weekly email. Once a week your site runs a delivery test and reports the result. Only Pro users can turn this off.' => 'Подсчитывает, сколько писем было отправлено или не отправлено, показывает их в виджете информационной панели и добавляет раздел статуса доставки электронной почты в еженедельное электронное письмо. Раз в неделю ваш сайт проводит тест доставки и сообщает о результате. Только пользователи Pro могут отключить это.',
  'Interval' => 'Интервал',
  'Next Billing Date' => 'Следующая дата выставления счета',
  'Yearly' => 'Ежегодно',
  'How to activate the Pro version of Flux Forms' => 'Как активировать Pro-версию Flux Forms',
  'Uploaded File' => 'Загруженный файл',
  'Your internet connection has been lost, but do not worry, we have saved the information you entered on this form. Once you are reconnected to the internet, you can easily send your information by clicking the submit button.' => 'Ваше подключение к Интернету прервано, но не волнуйтесь: мы сохранили информацию, которую вы ввели в эту форму. После повторного подключения к Интернету вы сможете легко отправить свою информацию, нажав кнопку «Отправить».',
  'Please ensure that you have a stable internet connection and try again.' => 'Убедитесь, что у вас стабильное подключение к Интернету, и повторите попытку.',
  'There was a problem uploading the file and the form was not submitted. Please check that your internet connection is stable and try again.' => 'При загрузке файла возникла проблема, и форма не была отправлена. Пожалуйста, проверьте стабильность вашего интернет-соединения и повторите попытку.',
  'You are experiencing issues with jQuery. Please contact the administrator for assistance. (Error code: JQ-500)' => 'У вас возникли проблемы с jQuery. Обратитесь за помощью к администратору. (Код ошибки: JQ-500)',
  'Your session has expired. Please refresh the page and try again.' => 'Ваш сеанс истек. Пожалуйста, обновите страницу и повторите попытку.',
  'Basic' => 'Базовый',
  'Sign-In|Up' => 'Войти|Вверх',
  'Advance' => 'Дополнительно',
  'Thank you Page' => 'Страница благодарности',
  'Redirect page' => 'Перенаправление страницы',
  'Please wait, you will be redirected shortly.' => 'Пожалуйста, подождите, вы будете перенаправлены в ближайшее время.',
  'Persia payment' => 'Персидский платеж',
  'Unlock Pro Features Today' => 'Разблокируйте функции Pro сегодня',
  'Upgrade to Pro for just %1$s%2$s%3$s/year and get access to powerful features, including advanced form fields, payment integrations, conditional logic, multi-step forms, file uploads, Security & Spam Protection, and priority support.%4$sView Pro Features%5$s' => 'Обновите версию Pro всего за%1$s%2$s%3$sв год и получите доступ к мощным функциям, включая расширенные поля форм, интеграцию платежей, условную логику, многошаговые формы, загрузку файлов, безопасность и защиту от спама, а также приоритетную поддержку.%4$sВозможности View Pro%5$s',
  'Add-on' => 'Дополнение',
  'Add-ons' => 'Дополнения',
  'Stripe Payment Add-on' => 'Дополнение Stripe Payment',
