  'Offline Forms Add-on' => 'Дополнение к автономным формам',
  'The Offline Forms add-on for Flux Forms allows users to save their progress when filling out forms in offline situations.' => 'Дополнение «Офлайн-формы» для Flux Forms позволяет пользователям сохранять прогресс при заполнении форм в автономном режиме.',
  'Please update Flux Forms before trying again.' => 'Пожалуйста, обновите Flux Forms, прежде чем повторить попытку.',
  'Activation of offline form mode.' => 'Активация режима офлайн-формы.',
  'Before activating this option, install' => 'Перед активацией этой опции установите',
  'To create a payment form to collect online payments, you must first install a payment add-on such as the Stripe Add-on.' => 'Чтобы создать платежную форму для сбора онлайн-платежей, необходимо сначала установить платежную надстройку, например надстройку Stripe.',
  'All formats' => 'Все форматы',
  'EFB SMS Add-on' => 'Дополнение EFB SMS',
  'Enable SMS functionality in your forms with the EFB SMS add-on, allowing you to validate mobile numbers and send confirmation codes via SMS, as well as receive notifications through SMS service.' => 'Включите функцию SMS в своих формах с помощью надстройки EFB SMS, которая позволит вам проверять номера мобильных телефонов и отправлять коды подтверждения через SMS, а также получать уведомления через службу SMS.',
  'Advanced confirmation code Add-on' => 'Дополнительный код подтверждения',
