  'Hijri Date' => 'Дата хиджры',
  'Install the add-on' => 'Установите дополнение',
  'Please go to the Add-ons Page of Flux Forms plugin and install the Jalili date addons' => 'Перейдите на страницу дополнений плагина Flux Forms и установите дополнения к дате Jalili.',
  'Please go to the Add-ons Page of Flux Forms plugin and install the Hijri date addons' => 'Перейдите на страницу дополнений плагина Flux Forms и установите дополнения к дате Хиджры.',
  'date & time' => 'дата и время',
  'Enable file upload in the response box' => 'Включить загрузку файлов в поле ответа',
  'Enable Google reCAPTCHA in the response box' => 'Включите Google reCAPTCHA в поле ответа',
  'Enable download button in the response box' => 'Включить кнопку загрузки в поле ответа',
  'Display the IP addresses of users in the response box.' => 'Отображение IP-адресов пользователей в поле ответа.',
  'Persia Payment Add-on' => 'Платежное дополнение Persia',
  'The Persia payment add-on for Flux Forms enables you to connect your website with Persia payment to process payments, donations, and online orders.' => 'Платежный модуль Persia для Flux Forms позволяет вам подключить свой веб-сайт к платежной системе Persia для обработки платежей, пожертвований и онлайн-заказов.',
  'Jalali Date Add-on' => 'Дополнение «Джалали»',
  'The Jalali Date add-on allows you to add a Jalali date field to your forms and create any type of form that includes this Shamsi date field.' => 'Дополнение «Дата Джалали» позволяет вам добавлять поле даты Джалали в ваши формы и создавать формы любого типа, включающие это поле даты Шамси.',
  'Hijri Date Add-on' => 'Дополнение к дате Хиджры',
  'The Hijri Date add-on allows you to add a Hijri date field to your forms and create any type of form that includes this field.' => 'Дополнение «Дата Хиджры» позволяет добавлять поле даты Хиджры в ваши формы и создавать формы любого типа, включающие это поле.',
  'SMS service Add-on' => 'Дополнение к SMS-сервису',
  'The SMS service add-on enables you to receive notification SMS messages when you or your customers receive new messages or responses.' => 'Дополнение службы SMS позволяет вам получать SMS-уведомления, когда вы или ваши клиенты получаете новые сообщения или ответы.',
  'Please install either the Hijri or Jalali date add-on. You cannot install both add-ons simultaneously.' => 'Установите дополнение к дате Хиджры или Джалали. Вы не можете установить оба дополнения одновременно.',
  'Response box' => 'Поле ответа',
  'Regions Drop-Down' => 'Раскрывающийся список «Регионы»',
  'You are seeing this message because your required add-ons are being installed. Please wait a few minutes and then visit this page again. If it has been more than five minutes and nothing has happened, please contact the support team of Flux Forms at Whitestudio.team.' => 'Вы видите это сообщение, потому что устанавливаются необходимые дополнения. Пожалуйста, подождите несколько минут, а затем посетите эту страницу еще раз. Если прошло более пяти минут и ничего не произошло, обратитесь в службу поддержки Flux Forms на сайте Whitestudio.team.',
  'The cell phone number is incorrect' => 'Номер мобильного телефона указан неверно',
  'Invalid country code' => 'Неверный код страны',
  'The cell phone number is too short' => 'Номер мобильного телефона слишком короткий',
  'The cell phone number is too long' => 'Номер мобильного телефона слишком длинный',
  'Please select the number of countries to display within an acceptable range.' => 'Пожалуйста, выберите количество стран для отображения в пределах допустимого диапазона.',
  'Disabled Field' => 'Отключенное поле',
  'Hidden Field' => 'Скрытое поле',
  'Select a country to display a list of states/provinces.' => 'Выберите страну для отображения списка штатов/провинций.',
  'Select a state/province to display a list of cities.' => 'Выберите штат/провинцию, чтобы отобразить список городов.',
  'SMS Service Add-on' => 'Дополнительная служба SMS',
  'This field is currently unavailable. Please contact the site administrator.' => 'Это поле в настоящее время недоступно. Пожалуйста, свяжитесь с администратором сайта.',
  'Would you like to customize the form using the colors of the active template?' => 'Хотите настроить форму, используя цвета активного шаблона?',
  'Flux Forms has utilized the colors of the active template. Please choose a color for each option below to customize the form you are creating based on the colors of your template. By selecting a color for each option below, the color of all form fields associated with that feature will change accordingly.' => 'Flux Forms использовал цвета активного шаблона. Пожалуйста, выберите цвет для каждого варианта ниже, чтобы настроить форму, которую вы создаете, на основе цветов вашего шаблона. При выборе цвета для каждого параметра ниже цвет всех полей формы, связанных с этой функцией, изменится соответствующим образом.',
  'Buttons text colors' => 'Цвета текста кнопок',
