  'SMS Notifications' => 'SMS-уведомления',
  'Enter the administrators’ mobile numbers to receive SMS notifications, such as alerts or new messages.' => 'Введите номера мобильных телефонов администраторов, чтобы получать SMS-уведомления, например оповещения или новые сообщения.',
