  'Click on the Settings button on the panel page of Flux Forms Plugin and configure the SMS sending method. Then, try again.' => 'Нажмите кнопку «Настройки» на странице панели плагина Flux Forms и настройте метод отправки SMS. Затем повторите попытку.',
