  'Screen recording is not supported on this device or browser (most mobile browsers do not allow it). Please open the form in a desktop browser such as Chrome, Edge or Firefox.' => 'Запись экрана не поддерживается на этом устройстве или в браузере (большинство мобильных браузеров не поддерживают это). Откройте форму в браузере на рабочем столе, например Chrome, Edge или Firefox.',
