  'The entered data does not match the form type. If you are an admin, please review the form type.' => 'Введенные данные не соответствуют типу формы. Если вы являетесь администратором, проверьте тип формы.',
  'Error: Please ensure there is only one form per page.' => 'Ошибка: убедитесь, что на странице имеется только одна форма.',
  'Your activation code has been verified. Enjoy all Pro features of Flux Forms.' => 'Ваш код активации проверен. Наслаждайтесь всеми функциями Flux Forms Pro.',
  'The confirmation code for this message is %s. By clicking the button below, you will be able to track messages and view received responses. If needed, you can also send a new reply.' => 'Код подтверждения для этого сообщения:%s. Нажав кнопку ниже, вы сможете отслеживать сообщения и просматривать полученные ответы. При необходимости вы также можете отправить новый ответ.',
  'To explore the full functionality and settings of Flux Forms, including email configurations, form creation options, and other features, simply delve into our %1$s documentation %2$s .' => 'Чтобы изучить все функциональные возможности и настройки Flux Forms, включая настройки электронной почты, параметры создания форм и другие функции, просто воспользуйтесь нашей документацией%1$s%2$s.',
  'Responses & Confirmation' => 'Ответы и подтверждение',
  'Test emails may land in your spam folder. If emails are not delivered, this is usually related to your hosting or email server configuration.server settings %1$sLearn how to fix email delivery issues%2$s or %3$scontact Flux Forms support%4$s.' => 'Тестовые письма могут попасть в папку со спамом. Если электронные письма не доставляются, это обычно связано с конфигурацией вашего хостинга или почтового сервера. Настройки сервера%1$sУзнайте, как устранить проблемы с доставкой электронной почты%2$sили%3$sОбратитесь в службу поддержки Flux Forms%4$s.',
  'From Address' => 'От адреса',
  'Make sure this email address matches the one configured in your SMTP settings to prevent email delivery issues.' => 'Убедитесь, что этот адрес электронной почты соответствует адресу, указанному в настройках SMTP, чтобы предотвратить проблемы с доставкой электронной почты.',
  'To preview the form, you need to save the built form and try again.' => 'Чтобы просмотреть форму, необходимо сохранить созданную форму и повторить попытку.',
  'No selected rows found.' => 'Выбранные строки не найдены.',
  'Mark as Read' => 'Отметить как прочитанное',
  'Require admin login to view responses' => 'Для просмотра ответов требуется вход администратора',
