  'After changing the Development Mode (Sandbox) option, save the settings, then deactivate and reactivate Flux Forms plugin from the Plugins page for the changes to take effect.' => 'После изменения параметра «Режим разработки (песочница)» сохраните настройки, затем деактивируйте и повторно активируйте плагин Flux Forms на странице «Плагины», чтобы изменения вступили в силу.',
  'I have read and agree to %1$sthe terms and conditions%2$s' => 'Я прочитал%1$sусловия использования%2$sи согласен с ними ',
