  'Enable Location Picker in Flux Forms' => 'Включить выбор местоположения в формах Flux',
  'Flux Forms cannot display the form because jQuery is not properly loaded. This issue might be due to incorrect jQuery invocation by another plugin or the current website theme.' => 'Flux Forms не может отобразить форму, поскольку jQuery загружен неправильно. Эта проблема может быть связана с неправильным вызовом jQuery другим плагином или текущей темой веб-сайта.',
  'Telegram Notification Add-on' => 'Дополнение для уведомлений Telegram',
  'The Telegram notification add-on lets you get notifications on your Telegram app whenever you receive new messages or responses' => 'Дополнение уведомлений Telegram позволяет вам получать уведомления в приложении Telegram всякий раз, когда вы получаете новые сообщения или ответы.',
  'Enter a location name' => 'Введите название местоположения',
  'The %1$s pages are currently unavailable. It looks like another plugin is causing a conflict with %1$s . To fix this issue, %2$s contact %1$s support %3$s for assistance or try disabling your plugins one at a time to identify the one causing the conflict.' => 'Страницы%1$sв настоящее время недоступны. Похоже, другой плагин вызывает конфликт с%1$s. Чтобы устранить эту проблему,%2$sобратитесь в службу поддержки%1$s%3$sза помощью или попробуйте отключить плагины по одному, чтобы определить тот, который вызывает конфликт.',
  'Send email with submitted form content only' => 'Отправлять электронное письмо только с отправленным содержимым формы',
  '%s copied!' => '%sскопировано!',
