  'Your session has expired or is no longer valid. Please refresh the page to continue.' => 'Ваша сессия истекла или больше не действительна. Пожалуйста, обновите страницу, чтобы продолжить.',
  'Your account has been successfully activated. You can now log in and get started!' => 'Ваша учетная запись успешно активирована. Теперь вы можете войти в систему и начать!',
  'You\'re all done' => 'Все готово',
