  'Geolocation is not supported by this browser.' => 'Геолокация не поддерживается этим браузером.',
  'verify' => 'проверить',
  'The form cannot be submitted because it requires a payment method, which is currently missing. If you are the Admin, please add a payment method to the form or change the form type to "Form" or "Survey".' => 'Невозможно отправить форму, поскольку для нее требуется способ оплаты, который в настоящее время отсутствует. Если вы являетесь администратором, добавьте в форму способ оплаты или измените тип формы на «Форма» или «Опрос».',
  'Cache Plugin Detected' => 'Обнаружен плагин кэша',
  'The following cache plugins may interfere with form functionality. If you experience issues, please review the documentation.' => 'Следующие плагины кэша могут мешать работе формы. Если у вас возникли проблемы, просмотрите документацию.',
  'Read more about cache compatibility' => 'Подробнее о совместимости кэша',
  'Dismiss All' => 'Отклонить все',
  'Dismiss %s' => 'Отклонить%s',
  'Security Plugin Detected' => 'Обнаружен плагин безопасности',
  'The following security plugin may block form submissions with 403 errors. It may block the REST API, remove the X-WP-Nonce header, or apply firewall rules to form requests.' => 'Следующий плагин безопасности может блокировать отправку форм с ошибкой 403. Он может заблокировать REST API, удалить заголовок X-WP-Nonce или применить правила брандмауэра для формирования запросов.',
  'Read more about security plugin compatibility' => 'Подробнее о совместимости плагинов безопасности',
  'Auto-Populate Add-on' => 'Автозаполнение дополнения',
  'The Auto-Populate add-on enables you to automatically populate form fields from datasets, previously submitted forms, or external APIs.' => 'Дополнение «Автозаполнение» позволяет автоматически заполнять поля форм из наборов данных, ранее отправленных форм или внешних API.',
  'Form Security & Spam Protection' => 'Безопасность форм и защита от спама',
  'Behavior-based anti-spam and API abuse protection with rate limits and a stop-loss for paid notifications such as SMS, Telegram, email and webhooks.' => 'Защита от спама на основе поведения и защита от злоупотреблений API с ограничениями скорости и стоп-лоссом для платных уведомлений, таких как SMS, Telegram, электронная почта и веб-перехватчики.',
  'Google Sheet Add-on' => 'Дополнение Google Таблиц',
  'Automatically send form submissions to your Google Sheets in real time. Connect a service account, map fields to columns, and keep a live, styled spreadsheet of every response — no webhook or browser login required.' => 'Автоматически отправляйте отправленные формы в Google Таблицы в режиме реального времени. Подключите сервисный аккаунт, сопоставьте поля со столбцами и сохраняйте действующую стилизованную электронную таблицу каждого ответа — вебхук или вход в браузер не требуется.',
  'Please fill in all required fields' => 'Пожалуйста, заполните все обязательные поля',
  'Email Server Status' => 'Состояние почтового сервера',
  'The test email never arrived' => 'Тестовое письмо так и не пришло',
  'Your WordPress site cannot send emails reliably. This is a very common hosting issue — the default PHP mail function is often blocked or ends up in spam. Installing an SMTP plugin routes your emails through a verified mail service and fixes this in minutes.' => 'Ваш сайт WordPress не может надежно отправлять электронные письма. Это очень распространенная проблема с хостингом — функция почты PHP по умолчанию часто блокируется или попадает в спам. Установка плагина SMTP направляет вашу электронную почту через проверенную почтовую службу и устраняет проблему за считанные минуты.',
  'WordPress sent the email - it just never arrived' => 'WordPress отправил электронное письмо, но оно так и не пришло',
  'Your site handed the message to your mail server successfully, so WordPress and this plugin did their part. It was lost, delayed or rejected afterwards - most often the receiving mailbox filed it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.' => 'Ваш сайт успешно передал сообщение на ваш почтовый сервер, поэтому WordPress и этот плагин внесли свой вклад. Впоследствии оно было потеряно, задержано или отклонено — чаще всего получающий почтовый ящик считал его спамом, или ваш хост не доставлял его из исходящей очереди. Это решается отправкой через службу SMTP с записями SPF и DKIM для вашего домена.',
  'WordPress could not send the email' => 'WordPress не удалось отправить электронное письмо',
  'The message never left your website: WordPress returned an error while sending it. Install and configure an SMTP plugin, or ask your host whether PHP mail is disabled.' => 'Сообщение так и не покинуло ваш сайт: WordPress вернул ошибку при отправке. Установите и настройте плагин SMTP или спросите у своего хостера, отключена ли почта PHP.',
  'Your emails arrive, but will most likely land in spam' => 'Ваши письма доходят, но, скорее всего, попадут в спам',
  'Delivery itself works - the test message reached us. What is missing is trust: sending through an SMTP service and adding SPF and DKIM records for your domain is what moves your emails from the spam folder to the inbox.' => 'Сама доставка работает - до нас дошло тестовое сообщение. Чего не хватает, так это доверия: отправка через службу SMTP и добавление записей SPF и DKIM для вашего домена — вот что перемещает ваши электронные письма из папки со спамом в папку «Входящие».',
  'The test email was delivered with a deliverability score of %1$s out of 100. Under %2$s, most mailboxes file messages in the spam folder, so the people filling in your forms may never see them.' => 'Тестовое электронное письмо было доставлено с оценкой доставляемости%1$sиз 100. При использовании%2$sбольшинство почтовых ящиков отправляют сообщения в папку «Спам», поэтому люди, заполняющие ваши формы, могут их никогда не увидеть.',
  'Step-by-step SMTP setup guide' => 'Пошаговое руководство по настройке SMTP',
  'Your email server is working. A detailed HTML report has been sent to %s.' => 'Ваш почтовый сервер работает. Подробный отчет в формате HTML отправлен на адрес%s.',
  'your admin email address' => '\\ваш адрес электронной почты администратора',
  'Spam Score Report on the Way!' => 'Отчет о спаме уже в пути!',
  'A complete email health report — including your spam score, deliverability details, and recommendations — will be sent to %s within the next few minutes.' => 'Полный отчет о состоянии электронной почты, включая оценку спама, сведения о доставляемости и рекомендации, будет отправлен на адрес%sв течение следующих нескольких минут.',
  'Email notifications may not be delivered' => 'Уведомления по электронной почте могут не доставляться',
  'This form\'s email notification feature is enabled, but email delivery has not been verified and the latest spam score is %s/100. The form was saved, but admin notification emails may not reach you until SMTP/email delivery is fixed.' => 'Функция уведомления по электронной почте в этой форме включена, но доставка электронной почты не проверена, а последняя оценка спама —%s/100. Форма была сохранена, но электронные письма с уведомлениями администратора могут не дойти до вас, пока доставка SMTP/электронной почты не будет исправлена.',
  'Notification emails are turned off' => 'Уведомления по электронной почте отключены',
  'Flux Forms will not send any email — neither to you nor to the person who submits this form — until "This site can send emails" is enabled in Email Settings.' => 'Flux Forms не будет отправлять электронные письма — ни вам, ни лицу, отправившему эту форму, — до тех пор, пока в настройках электронной почты не будет включен параметр «Этот сайт может отправлять электронные письма».',
  'Enable email sending' => 'Включить отправку электронной почты',
  'Click "Check Email Server" to test delivery, turn this switch on, then press Save.' => 'Нажмите «Проверить сервер электронной почты», чтобы проверить доставку, включите этот переключатель, затем нажмите «Сохранить».',
  'Delivery is taking longer than expected' => 'Доставка занимает больше времени, чем ожидалось',
  'WordPress sent the test email, but our server has not received it yet. This may be a temporary delay. Check the diagnostics below to troubleshoot.' => 'WordPress отправил тестовое письмо, но наш сервер еще не получил его. Это может быть временная задержка. Чтобы устранить неполадки, проверьте приведенную ниже диагностику.',
  'Prepare Test' => 'Подготовка теста',
  'Connecting to WhiteStudio to generate a unique test email address.' => 'Подключение к WhiteStudio для создания уникального тестового адреса электронной почты.',
  'WordPress Sends the Email' => 'WordPress отправляет электронное письмо',
  'WordPress hands a real message to your mail server. A tick here means WordPress sent it, not yet that it arrived.' => 'WordPress передает на ваш почтовый сервер настоящее сообщение. Галочка здесь означает, что WordPress отправил его, но он еще не прибыл.',
  'Waiting for Delivery' => 'Ожидание доставки',
  'Checking whether the test email arrived at our server (usually takes a few seconds).' => 'Проверка того, пришло ли тестовое письмо на наш сервер (обычно занимает несколько секунд).',
  'Quick Result' => 'Быстрый результат',
  'Showing the first delivery result — you will see right away if email is working.' => 'Показываем первый результат доставки — вы сразу увидите, работает ли электронная почта.',
  'Full Report' => 'Полный отчет',
  'A detailed HTML report with full diagnostics is being prepared and emailed to you.' => 'Подготовленный отчет в формате HTML с полной диагностикой будет отправлен вам по электронной почте.',
  'Needs attention' => 'Требует внимания',
  '%s of 5 steps done' => '%sиз 5 шагов выполнено',
  'Step %s of 5' => 'Шаг%sиз 5',
  '/ 100' => '/ 100',
  'Test started' => 'Тест начался',
  'A unique address is being generated for this test.' => 'Для этого теста создается уникальный адрес.',
  'Waiting for the email to arrive' => 'Ожидание прибытия письма',
  'We check our server every few seconds. Please keep this page open.' => 'Мы проверяем наш сервер каждые несколько секунд. Пожалуйста, оставьте эту страницу открытой.',
  'Your email server is healthy' => 'Ваш почтовый сервер исправен',
  'The test email arrived, and the subject and unique-code checks both passed.' => 'Тестовое письмо пришло, и проверка темы и уникального кода прошла успешно.',
  'Delivered, but likely to be filtered as spam' => 'Доставлено, но, вероятно, будет отфильтровано как спам',
  'Delivered, but deliverability is weak' => 'Доставлено, но доставляемость низкая',
  'No email arrived' => 'Письмо не пришло',
  'Nothing was received during the test window, so your server most likely cannot send email.' => 'Во время тестового окна ничего не было получено, поэтому ваш сервер, скорее всего, не может отправлять электронную почту.',
  'The test timed out' => 'Тайм-аут теста истек',
  'The test reached its time limit. Your server may be slow, or may block outbound email.' => 'Испытание достигло лимита времени. Ваш сервер может работать медленно или блокировать исходящую электронную почту.',
  'The test email could not be sent' => 'Не удалось отправить тестовое письмо',
  'WordPress returned an error while sending. See the message below.' => 'WordPress возвратил ошибку при отправке. См. сообщение ниже.',
  'The connection was lost' => 'Соединение потеряно',
  'No answer came back from the server. Refresh the page and try again.' => 'От сервера не получен ответ. Обновите страницу и повторите попытку.',
  'This test needs a higher plan' => 'Этот тест требует более высокого плана',
  'Upgrade your plan to run the full delivery test.' => 'Обновите свой план, чтобы провести полную проверку доставки.',
  'Your email server is working. A detailed HTML report has been sent to' => 'Ваш почтовый сервер работает. Подробный отчет в формате HTML отправлен на адрес',
  'A complete email health report — including your spam score, deliverability details, and recommendations — will be sent within the next few minutes to' => 'Полный отчет о состоянии электронной почты, включая оценку спама, сведения о доставляемости и рекомендации, будет отправлен в течение следующих нескольких минут на адрес',
  'Upgrade required' => 'Требуется обновление',
