  'Score: %s' => 'Оценка:%s',
  'Upgrade' => 'Обновить',
  'The test timed out. Please try again — your server may be slow or blocking outgoing mail.' => 'Тайм-аут теста истек. Пожалуйста, попробуйте еще раз — возможно, ваш сервер работает медленно или блокирует исходящую почту.',
  'Waiting for the test email to arrive…' => 'Ожидание тестового письма...',
