  'Mains' => 'Сеть',
  'Drinks' => 'Напитки',
  'Sides/Appetizers' => 'гарниры/закуски',
  'Avg Length' => 'Средняя длина',
  'Offline Forms' => 'Офлайн-формы',
  'Persia Payment' => 'Персидский платеж',
  'Persian Date Picker' => 'Персидский выбор даты',
  'Arabic Date Picker' => 'Выбор даты на арабском языке',
  'Google Sheets' => 'Google Таблицы',
  'Conditional Logic' => 'Условная логика',
  'Your subscription needs renewing before the missing add-ons can be restored.' => 'Вашу подписку необходимо продлить, прежде чем можно будет восстановить недостающие дополнения.',
  'The missing add-on files could not be restored. Check the server connection and file permissions, then try again.' => 'Отсутствующие файлы дополнения не удалось восстановить. Проверьте подключение к серверу и права доступа к файлу, затем повторите попытку.',
  'You do not have permission to do this.' => 'У вас нет разрешения на это.',
  'All required add-ons were restored.' => 'Все необходимые дополнения были восстановлены.',
  'Finish updating Flux Forms' => 'Завершить обновление форм Flux',
  'Some add-on files are missing' => 'Некоторые дополнительные файлы отсутствуют',
  'The plugin was updated, so its add-ons must be reinstalled before this page can load. Click the button below to install them.' => 'Плагин был обновлен, поэтому его надстройки необходимо переустановить, прежде чем эта страница сможет загрузиться. Нажмите кнопку ниже, чтобы установить их.',
  'One or more add-on files are missing. Click the button below to reinstall them.' => 'Отсутствует один или несколько дополнительных файлов. Нажмите кнопку ниже, чтобы переустановить их.',
  'Automatic recovery was attempted but did not finish. Review the reason below, fix it if necessary, then try again.' => 'Попытка автоматического восстановления не завершилась. Просмотрите причину ниже, при необходимости устраните ее и повторите попытку.',
  'Recover add-ons' => 'Восстановить дополнения',
  'Installing add-ons…' => 'Установка дополнений...',
  'Installation complete.' => 'Установка завершена.',
  'Click to activate the add-ons.' => 'Нажмите, чтобы активировать дополнения.',
  'Activate add-ons' => 'Активировать дополнения',
  'Installation failed. Please try again.' => 'Установка не удалась. Пожалуйста, попробуйте еще раз.',
  'Missing add-ons:' => 'Отсутствуют дополнения:',
  'Why the recovery failed' => 'Почему восстановление не удалось',
  'Preparing your form' => 'Подготовка формы',
  'Add-ons restored successfully' => 'Дополнения успешно восстановлены',
  'The form is being prepared. This page will reload automatically.' => 'Форма находится в стадии подготовки. Эта страница перезагрузится автоматически.',
  'The page will reload automatically so the restored add-ons can be activated.' => 'Страница перезагрузится автоматически, чтобы можно было активировать восстановленные дополнения.',
  'Reload now' => 'Перезагрузить сейчас',
  'This form is temporarily unavailable.' => 'Эта форма временно недоступна.',
  'We could not restore a required form component automatically. Please try again shortly; the site administrator can view the exact recovery error in Flux Forms.' => 'Не удалось автоматически восстановить необходимый компонент формы. Пожалуйста, повторите попытку через некоторое время; администратор сайта может просмотреть точную ошибку восстановления в формах Flux.',
  'The add-on is already installed.' => 'Дополнение уже установлено.',
  'File access status not checked yet. Please wait.' => 'Состояние доступа к файлу еще не проверено. Пожалуйста, подождите.',
  'Error: server (%s) responded with an invalid request. responded code: %s' => 'Ошибка: сервер (%s) ответил неверным запросом. код ответа:%s',
  'Cannot install add-ons of Flux Forms because the plugin is not able to connect to the %s server' => 'Невозможно установить дополнения Flux Forms, поскольку плагин не может подключиться к серверу%s',
  'Your Easy Form Builder Pro subscription has expired, so the Pro add-ons could not be downloaded. The plugin keeps working without them. Renew your subscription to restore all Pro features:' => 'Срок действия вашей подписки на Easy Form Builder Pro истек, поэтому дополнения Pro невозможно загрузить. Плагин продолжает работать и без них. Продлите подписку, чтобы восстановить все функции Pro:',
  'The version of the add-on is not compatible with the version of the Flux Forms plugin.' => 'Версия дополнения несовместима с версией плагина Flux Forms.',
  'Cannot install add-ons of Flux Forms because the plugin is not able to download files' => 'Невозможно установить дополнения Flux Forms, поскольку плагин не может загружать файлы',
  'Cannot install add-ons because this server has disabled the PHP filesystem functions needed to prepare the download. Please ask your hosting provider to enable mkdir and rename, or configure the WordPress filesystem.' => 'Невозможно установить дополнения, поскольку на этом сервере отключены функции файловой системы PHP, необходимые для подготовки загрузки. Попросите вашего хостинг-провайдера включить mkdir и переименовать или настроить файловую систему WordPress.',
  'Cannot install add-ons of Flux Forms because the plugin is not able to move the downloaded file' => 'Невозможно установить дополнения Flux Forms, поскольку плагин не может переместить загруженный файл',
  'Cannot install add-ons of Flux Forms because the plugin is not able to unzip files' => 'Невозможно установить дополнения Flux Forms, поскольку плагин не может разархивировать файлы',
  'To fix this, sign in to your %s, download the Add-ons Handler plugin from the Downloads section, then install and activate it. After that, activate the add-ons you need from the Add-ons Handler plugin.' => 'Чтобы это исправить, войдите в свою учетную запись%s, загрузите плагин Add-ons Handler из раздела «Загрузки», затем установите и активируйте его. После этого активируйте нужные вам надстройки с помощью плагина Add-ons Handler.',
  'WhiteStudio dashboard' => 'Панель управления WhiteStudio',
  'This bundled add-on is missing from the plugin files.' => 'Это дополнение отсутствует в файлах плагина.',
  'The add-on server returned an unexpected response.' => 'Дополнительный сервер вернул неожиданный ответ.',
  'The add-on could not be installed.' => 'Не удалось установить дополнение.',
  'The add-on server did not provide a download URL.' => 'Сервер дополнений не предоставил URL-адрес для загрузки.',
  'The add-on download URL is not an approved Flux Forms source.' => 'URL-адрес загрузки дополнения не является одобренным источником Flux Forms.',
  'Your server could not reach %1$s, so the add-on could not be downloaded. This is almost always a firewall on your hosting blocking the outgoing request, not a problem with your licence. To install add-ons without any download at all, sign in at %2$s and download the Flux Forms Add-ons Handler plugin, then install it like any other plugin. It contains every add-on your licence covers.' => 'Ваш сервер не смог связаться с%1$s, поэтому дополнение не удалось загрузить. Почти всегда это брандмауэр на вашем хостинге, блокирующий исходящий запрос, а не проблема с вашей лицензией. Чтобы установить надстройки вообще без какой-либо загрузки, войдите в систему на%2$sи загрузите плагин Flux Forms Add-ons Handler, а затем установите его, как любой другой плагин. Он содержит все дополнения, на которые распространяется ваша лицензия.',
  'If you would rather fix the connection, ask your hosting provider why outgoing requests from %s are being blocked.' => 'Если вы предпочитаете исправить соединение, узнайте у своего хостинг-провайдера, почему блокируются исходящие запросы от%s.',
  'Flux Forms: add-on downloads are being blocked' => 'Flux Forms: загрузка дополнений блокируется',
  'Add-on affected: %s' => 'Затронуто дополнение:%s',
  'No response was recorded for this add-on.' => 'Для этого дополнения не было записано ни одного ответа.',
  'Writable' => 'Доступно для записи',
  'Not writable — the add-on folder cannot be created or extracted into.' => 'Недоступно для записи — папку дополнения невозможно создать или извлечь в нее.',
  'Blocked by WP_HTTP_BLOCK_EXTERNAL — outgoing requests are disabled on this site.' => 'Заблокировано WP_HTTP_BLOCK_EXTERNAL — на этом сайте отключены исходящие запросы.',
  'DISABLE_WP_CRON is on — background retries only run if a server cron task calls wp-cron.php.' => 'DISABLE_WP_CRON включен — фоновые повторные попытки выполняются только в том случае, если задача cron сервера вызывает wp-cron.php.',
  'Page that needed it' => 'Страница, которой это нужно',
  'Plugin version' => 'Версия плагина',
  'Add-on folder' => 'Папка дополнений',
  'Outgoing requests' => 'Исходящие запросы',
  'WP-Cron' => 'WP-Cron',
  'Attempts made' => 'Попытки',
  'Flux Forms could not reinstall its add-on files automatically. Forms that rely on those add-ons are showing a temporary message to visitors until this is resolved.' => 'Flux Forms не удалось автоматически переустановить дополнительные файлы. Формы, использующие эти надстройки, показывают посетителям временное сообщение, пока проблема не будет решена.',
  'What is missing' => 'Чего не хватает',
  'Diagnostics' => 'Диагностика',
  'What to do next' => 'Что делать дальше',
  'Open Flux Forms in your dashboard and use the Recover add-ons button.' => 'Откройте формы Flux на панели управления и используйте кнопку «Восстановить надстройки».',
  'If the add-on folder is not writable, ask your host to allow writing to the plugin folder.' => 'Если папка дополнения недоступна для записи, попросите вашего хостера разрешить запись в папку плагина.',
  'If outgoing requests are blocked, ask your host to allow connections to the Flux Forms update server.' => 'Если исходящие запросы заблокированы, попросите ваш хост разрешить подключения к серверу обновлений Flux Forms.',
  'If your Pro subscription has expired, renew it to restore the Pro add-ons.' => 'Если срок действия вашей подписки Pro истек, продлите ее, чтобы восстановить дополнения Pro.',
  'We have made some updates. Please wait a few minutes before trying again.' => 'Мы внесли некоторые обновления. Пожалуйста, подождите несколько минут, прежде чем повторить попытку.',
  'Cannot install add-ons of Flux Forms because the plugin is not able to connect to the whitestudio.team server' => 'Невозможно установить дополнения Flux Forms, поскольку плагин не может подключиться к серверу whitestudio.team',
  'One of the free features' => 'Одна из бесплатных функций',
  'Important: Caching Plugin May Affect Flux Forms' => 'Важно: плагин кэширования может повлиять на формы Flux',
  'The following caching plugins are active on your site:' => 'На вашем сайте активны следующие плагины кеширования:',
  'Plugin Name' => 'Имя плагина',
  'Slug' => 'Слизень',
  'Please note that these plugins may affect the functionality of Flux Forms.' => 'Обратите внимание, что эти плагины могут повлиять на функциональность Flux Forms.',
  'If you experience any issues, please exclude the page where your form is published from caching or disable these plugins. For detailed guidance on how to set up this exclusion, please refer to the documentation of the respective caching plugin.' => 'Если у вас возникли какие-либо проблемы, исключите страницу, на которой опубликована ваша форма, из кэширования или отключите эти плагины. Подробные инструкции по настройке этого исключения можно найти в документации соответствующего плагина кэширования.',
  'Sent by' => 'Отправлено',
  'Action needed: Flux Forms Pro is paused on %s' => 'Требуется действие: Flux Forms Pro приостановлен на%s',
  'Flux Forms could not confirm your Pro licence for %1$s days in a row, so the Pro features on %2$s are paused for now.' => 'Flux Forms не может подтвердить вашу лицензию Pro в течение%1$sдней подряд, поэтому функции Pro на%2$sна данный момент приостановлены.',
  'Your forms, entries and settings are untouched, every free feature keeps working, and your activation code is still stored &mdash; nothing was deleted.' => 'Ваши формы, записи и настройки не тронуты, все бесплатные функции продолжают работать, а ваш код активации по-прежнему сохраняется — ничего не было удалено.',
  'Open %1$sYT Form &rarr; Settings%2$s and press %1$sSave%2$s. That checks the licence again straight away; if the connection is back, Pro switches on within a minute.' => 'Откройте форму%1$sYT → Настройки%2$sи нажмите%1$sСохранить%2$s. Это немедленно проверяет лицензию еще раз; если соединение восстановится, Pro включится через минуту.',
  'Still paused? Ask your hosting provider to allow outgoing HTTPS connections to %s &mdash; a firewall, proxy or regional block is the usual cause &mdash; then repeat step 1.' => 'Все еще приостановлено? Попросите своего хостинг-провайдера разрешить исходящие HTTPS-соединения к%s(обычной причиной является брандмауэр, прокси-сервер или региональная блокировка), а затем повторите шаг 1.',
  'If your subscription has expired, or you moved this website to a new domain, %1$srenew or re-activate your licence%2$s and paste the new code into Settings.' => 'Если срок вашей подписки истек или вы переместили этот веб-сайт в новый домен,%1$sпродлите или повторно активируйте лицензию%2$sи вставьте новый код в настройки.',
  'First failed check' => 'Первая неудачная проверка',
  'Grace period' => 'льготный период',
  'Activation code' => 'Код активации',
  'Error code' => 'Код ошибки',
  'How to bring Pro back' => 'Как вернуть Pro',
  'Check my licence now' => 'Проверьте мою лицензию сейчас',
  'Still stuck? Send the details above to %1$sour support team%2$s and we will take it from there.' => 'Все еще застрял? Отправьте приведенную выше информацию%1$sв нашу службу поддержки%2$s, и мы примем меры.',
  'The licence server answered with an error and could not confirm your licence.' => 'Сервер лицензий ответил с ошибкой и не смог подтвердить вашу лицензию.',
  'Your website could not reach the licence server &mdash; almost always a network, firewall or DNS restriction on the hosting side.' => 'Ваш веб-сайт не может связаться с сервером лицензий — почти всегда из-за ограничений сети, брандмауэра или DNS на стороне хостинга.',
  'The licence server&rsquo;s answer arrived damaged, usually because a security plugin, proxy or CDN changed it on the way.' => 'Ответ сервера лицензий пришел поврежденным, обычно из-за того, что плагин безопасности, прокси-сервер или CDN изменили его по пути.',
  'The licence check could not be completed.' => 'Проверку лицензии не удалось завершить.',
  'Your activation code has expired!' => 'Срок действия вашего кода активации истек!',
  'Your Easy Form Builder Pro subscription has expired. To continue using the %s add-on and all Pro features, please renew your subscription.' => 'Срок действия вашей подписки на Easy Form Builder Pro истек. Чтобы продолжить использование дополнения%sи всех функций версии Pro, продлите подписку.',
  'Renew Subscription' => 'Обновить подписку',
  'Pro Version Required' => 'Требуется Pro-версия',
  'The %s add-on is a Pro feature. Please upgrade to Flux Forms Pro to access this functionality.' => 'Дополнение%s— это функция Pro. Пожалуйста, обновите Flux Forms Pro, чтобы получить доступ к этой функции.',
  'Your Easy Form Builder Pro subscription has expired. To continue enjoying all Pro features and keep your forms running, %1$sRenew your subscription now.%2$s' => 'Срок действия вашей подписки на Easy Form Builder Pro истек. Чтобы и дальше пользоваться всеми функциями версии Pro и поддерживать работоспособность форм,%1$sпродлите подписку прямо сейчас.%2$s',
  'The payment could not be verified yet.' => 'Платеж пока не удалось подтвердить.',
  'This payment provider does not support refunds from the site.' => 'Этот поставщик платежей не поддерживает возврат средств с сайта.',
  'Trial' => 'Пробная версия',
  'Canceled' => 'Отменено',
  'Amount mismatch' => 'Несоответствие суммы',
  'Unpaid' => 'Неоплачиваемый',
  'Incomplete' => 'Неполный',
  'Expired' => 'Срок действия истек',
  'Sorry, you are not allowed to access this page.' => 'К сожалению, у вас нет доступа к этой странице.',
  'Payments taken through your forms, from every payment provider. API keys and the active provider are set on the plugin Settings page, Payment tab.' => 'Платежи, принимаемые через ваши формы от каждого поставщика платежей. Ключи API и активный провайдер задаются на странице настроек плагина, вкладка «Оплата».',
  'A Stripe webhook signing secret starts with "whsec_".' => 'Секрет подписи вебхука Stripe начинается с «whsec_».',
  'Providers and webhooks' => 'Поставщики и веб-перехватчики',
  'Configured' => 'Настроено',
  'Not configured' => 'Не настроено',
  'Webhook URL for this provider (if it sends payment notifications):' => 'URL вебхука для этого провайдера (если он отправляет уведомления о платежах):',
  'Recent payments' => 'Последние платежи',
  'No payments yet.' => 'Платежей пока нет.',
  'Confirmation code' => 'Код подтверждения',
  'Transaction ID' => 'Идентификатор транзакции',
  'Subscription' => 'Подписка',
  'One-time' => 'Одноразовый',
  'The latest %d payments are shown.' => 'Отображаются последние платежи%d.',
  'Test provider (development only)' => 'Поставщик тестов (только для разработки)',
  'Test outcome' => 'Результат теста',
  'Approve every payment' => 'Подтвердить каждый платеж',
  'Decline every payment' => 'Отклонять каждый платеж',
  'No money is taken. Development only.' => 'Деньги не берутся. Только разработка.',
  'TEST MODE: no card is charged.' => 'ТЕСТОВЫЙ РЕЖИМ: оплата с карты не взимается.',
  'Test provider: the payment was declined.' => 'Провайдер тестирования: платеж отклонен.',
  'Publishable key' => 'Публикуемый ключ',
  'Stripe is not configured on this site. Please contact the site administrator.' => 'Stripe не настроен на этом сайте. Пожалуйста, свяжитесь с администратором сайта.',
  'The payment method of this form is not supported.' => 'Способ оплаты, указанный в этой форме, не поддерживается.',
  'The payment could not be started. Please try again.' => 'Не удалось начать платеж. Пожалуйста, попробуйте еще раз.',
  'Optional but recommended: in the Stripe Dashboard add a webhook endpoint with this URL and the events payment_intent.succeeded, payment_intent.payment_failed, payment_intent.canceled, charge.refunded, customer.subscription.updated and customer.subscription.deleted, then paste its signing secret below.' => 'Необязательно, но рекомендуется: на панели управления Stripe добавьте конечную точку веб-перехватчика с этим URL-адресом и событиями pay_intent.succeeded, pay_intent.pay_failed, pay_intent.canceled, charge.refunded, customer.subscription.updated и customer.subscription.deleted, а затем вставьте секрет подписи ниже.',
  'Webhook signing secret' => 'Секрет подписи вебхука',
  'Saved - leave empty to keep it' => 'Сохранено: оставьте пустым, чтобы сохранить его.',
  'Remove the saved secret' => 'Удалить сохраненный секрет',
  'Invalid or expired nonce' => 'Неверный или просроченный одноразовый номер',
  'No payment provider is available on this site. Please contact the site administrator.' => 'На этом сайте нет платежных систем. Пожалуйста, свяжитесь с администратором сайта.',
  'Too many payment attempts. Please wait a few minutes and try again.' => 'Слишком много попыток оплаты. Пожалуйста, подождите несколько минут и повторите попытку.',
  'Invalid payment data. Please refresh the page and try again.' => 'Неверные данные платежа. Пожалуйста, обновите страницу и повторите попытку.',
  'The payment provider is not configured on this site. Please contact the site administrator.' => 'Поставщик платежей не настроен на этом сайте. Пожалуйста, свяжитесь с администратором сайта.',
  'No payment amount detected. Please review your selected items and try again. If the problem persists, contact support.' => 'Сумма платежа не обнаружена. Пожалуйста, проверьте выбранные элементы и повторите попытку. Если проблема не устранена, обратитесь в службу поддержки.',
  'Too many requests. Please wait a moment and try again.' => 'Слишком много запросов. Пожалуйста, подождите немного и повторите попытку.',
  'Payment not found.' => 'Платеж не найден.',
  'Your payment has not been confirmed yet. Please wait a moment and try again. If the problem persists, contact the site administrator.' => 'Ваш платеж еще не подтвержден. Пожалуйста, подождите немного и повторите попытку. Если проблема не устранена, обратитесь к администратору сайта.',
  'Online payment is not available at the moment. Please try again later or contact us.' => 'Онлайн-оплата в данный момент недоступна. Пожалуйста, повторите попытку позже или свяжитесь с нами.',
  'Active payment provider' => 'Активный поставщик платежей',
  'Payment forms take card payments through this provider. Only installed providers are listed.' => 'Платежные формы принимают платежи по картам через этого провайдера. В списке указаны только установленные поставщики.',
  'Saved — leave empty to keep' => 'Сохранено — оставьте пустым, чтобы сохранить',
