  'Quarantined' => 'На карантине',
  'Cost Suppressed' => 'Стоимость снижена',
  'Protection summary' => 'Сводка по защите',
  'Current operating mode and the most important thresholds.' => 'Текущий режим работы и наиболее важные пороговые значения.',
  'Submit score' => 'Отправить оценку',
  'Paid notification score' => 'Оценка платных уведомлений',
