  'Request protection' => 'Запросить защиту',
  'Controls that run before EFB REST callbacks.' => 'Элементы управления, которые выполняются перед обратными вызовами EFB REST.',
  'Enable Human Shield' => 'Включить «Живой щит»',
  'Activate behavior tokens and rate limits.' => 'Активируйте жетоны поведения и ограничения скорости.',
  'Monitor logs only; soft block is recommended for production rollout.' => 'Отслеживать только журналы; для производственного развертывания рекомендуется мягкий блок.',
  'Minimum submit score' => 'Минимальный балл за отправку',
