  'Protects payment REST routes.' => 'Защищает платежные маршруты REST.',
  'File upload budget' => 'Бюджет загрузки файлов',
  'Flux Forms already limits uploads on its own: each visitor may upload three files per file field on the form, and the response box allows three. Leave a box at 0 to keep that automatic behaviour, or enter a number to set it yourself.' => 'Flux Forms уже ограничивает загрузку самостоятельно: каждый посетитель может загрузить три файла на одно поле формы в форме, а поле ответа позволяет три. Оставьте в поле 0, чтобы сохранить автоматическое поведение, или введите число, чтобы настроить его самостоятельно.',
  'Uploads allowed per file field' => 'Загрузки разрешены для каждого поля файла',
  'Default 3, so a two-field form allows six uploads. 0 keeps the default.' => 'По умолчанию 3, поэтому форма с двумя полями допускает шесть загрузок. 0 сохраняет значение по умолчанию.',
  'Total uploads per visitor' => 'Общее количество загрузок на посетителя',
  'A fixed total that ignores how many fields the form has. 0 keeps the automatic per-field calculation.' => 'Фиксированная сумма, которая игнорирует количество полей в форме. 0 сохраняет автоматический расчет для каждого поля.',
  'Budget resets after (seconds)' => 'Бюджет сбрасывается через (секунды)',
  'Default 3600 (one hour). 0 keeps the default.' => 'По умолчанию 3600 (один час). 0 сохраняет значение по умолчанию.',
  'Maximum file size (MB)' => 'Максимальный размер файла (МБ)',
  'A site-wide ceiling. It can only tighten a per-field limit, never widen it. 0 keeps the field setting.' => 'Потолок по всему объекту. Он может только ужесточить ограничение на каждое поле, но никогда не расширять его. 0 сохраняет настройку поля.',
  'Protect response lookup' => 'Защитить поиск ответа',
  'Rate-limit tracking-code searches by request count (no human-token check).' => 'Ограничение скорости поиска кода отслеживания по количеству запросов (без проверки человеческого токена).',
  'Manual access lists' => 'Списки ручного доступа',
  'One entry per line: an exact IP or a wildcard prefix such as 203.0.113.* — allowlist bypasses all checks, blocklist blocks in every mode.' => 'Одна запись в строке: точный IP-адрес или префикс подстановочного знака, например 203.0.113.* — список разрешенных обходит все проверки, список блокировок блокируется в каждом режиме.',
  'IP allowlist' => 'Список разрешенных IP-адресов',
  'Trusted IPs that skip the shield completely (your office, monitoring bots).' => 'Доверенные IP-адреса, которые полностью игнорируют защиту (ваш офис, мониторинг ботов).',
  'IP blocklist' => 'Черный список IP-адресов',
  'IPs that are always blocked on protected form routes.' => 'IP-адреса, которые всегда блокируются на маршрутах защищенной формы.',
  'Minimum paid notification score' => 'Минимальный балл платных уведомлений',
  'Suppress costly notifications below this score.' => 'Подавить дорогостоящие уведомления ниже этого значения.',
  'SMS daily stop-loss' => 'Дневной стоп-лосс по SMS',
  'Global SMS budget per day, across all recipients.' => 'Глобальный дневной бюджет SMS для всех получателей.',
  'Telegram daily stop-loss' => 'Дневной стоп-лосс в Telegram',
  'Global Telegram budget per day, across all recipients.' => 'Глобальный дневной бюджет Telegram для всех получателей.',
  'Webhook/Email daily stop-loss' => 'Webhook/ежедневный стоп-лосс по электронной почте',
  'Global webhook/email/sheet budget per day.' => 'Глобальный дневной бюджет веб-перехватчика/электронной почты/таблицы.',
  'Per-recipient daily cap' => 'Дневное ограничение на каждого получателя',
  'Maximum notifications per single recipient per day (0 disables).' => 'Максимальное количество уведомлений на одного получателя в день (0 — отключить).',
  'These limits become active for paid services after the core integration filter is added.' => 'Эти ограничения становятся активными для платных услуг после добавления основного фильтра интеграции.',
  'Decisions — last 24 hours' => 'Решения — за последние 24 часа',
  'Stacked per hour: allowed, blocked, quarantined and monitored requests.' => 'Складывается в час: разрешенные, заблокированные, помещенные в карантин и отслеживаемые запросы.',
  'No decisions recorded in the last 24 hours.' => 'За последние 24 часа решений не зарегистрировано.',
