  'Retest' => 'Повторное тестирование',
  'Let’s connect Google Sheets — about 3 minutes, one time' => 'Давайте подключим Google Таблицы — примерно 3 минуты, один раз», «ru»]]',
  'Follow the numbered steps on the right to download a free service account key from Google, then drop the file below. You only do this once. After that, creating a sheet for any form is a couple of clicks.' => 'Выполните пронумерованные шаги справа, чтобы загрузить бесплатный ключ сервисной учетной записи от Google, а затем перетащите файл ниже. Вы делаете это только один раз. После этого создание листа для любой формы — это пара кликов.',
  'Your Google email' => 'Ваш адрес электронной почты Google',
  '(recommended)' => '(рекомендуется)',
  'Any sheet the plugin <strong>creates</strong> is automatically shared to this address, so it appears in your own Google Drive under “Shared with me.” Without it, new sheets stay hidden inside the service account.' => 'Любой лист, который плагин<strong>создает</strong>, автоматически передается по этому адресу, поэтому он появляется на вашем Google Диске в разделе «Доступно мне». Без этого новые листы останутся скрытыми внутри учетной записи службы.',
  'Enable Google Sheet Integration' => 'Включить интеграцию с Google Таблицами',
  'Sync form submissions to your spreadsheets automatically' => 'Автоматическая синхронизация отправленных форм с вашими таблицами',
  'Drag & drop service account JSON file(s) here' => 'Перетащите сюда файлы JSON сервисного аккаунта',
  'or click to browse — you can add multiple service accounts at once' => '\\или не нажимайте для просмотра — вы можете добавить несколько сервисных аккаунтов одновременно',
  'Connected service accounts' => 'Подключенные сервисные аккаунты',
  'One-time setup (≈3 min)' => 'Однократная установка (≈3 минуты)',
  'Go to <a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a> &rarr; Project dropdown (top-left) &rarr; New Project &rarr; name it &rarr; Create' => 'Перейдите на<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ раскрывающийся список «Проект» (вверху слева) → «Новый проект» → назовите его → «Создать».',
  'APIs &amp; Services &rarr; Library &rarr; enable <strong>Google Sheets API</strong> <em>and</em> <strong>Google Drive API</strong>' => 'API и службы → Библиотека → включить<strong>Google Sheets API</strong><em>и</em><strong>Google Drive API</strong>',
  'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; name it &rarr; Done' => 'API и службы → Учетные данные → Создать учетные данные → Учетная запись службы → назовите ее → Готово',
  'Open the service account &rarr; Keys tab &rarr; Add Key &rarr; Create New Key &rarr; JSON (downloads automatically)' => 'Откройте сервисный аккаунт → вкладка «Ключи» → «Добавить ключ» → «Создать новый ключ» → JSON (загружается автоматически)',
  'Drag that downloaded file into the box on the left — it is tested automatically' => 'Перетащите загруженный файл в поле слева — он проверяется автоматически',
  'Add <strong>Your Google email</strong> above so created sheets land in your Drive' => 'Добавьте<strong>свой адрес электронной почты Google</strong>, указанный выше, чтобы созданные листы попадали на ваш Диск.',
  'Please choose a valid .json key file.' => 'Пожалуйста, выберите действительный файл ключей .json.',
  'Could not read file: %s' => 'Не удалось прочитать файл:%s',
  'Connecting service account…' => 'Подключение сервисного аккаунта...',
  'Service account added.' => 'Служебный аккаунт добавлен.',
  'Saved. New sheets created by the plugin will be shared to %s automatically.' => 'Сохранено. Новые листы, созданные плагином, будут автоматически доступны%s.',
  'Email cleared. New sheets will stay inside the service account until you share them.' => 'Электронная почта удалена. Новые листы останутся в сервисном аккаунте, пока вы не поделитесь ими.',
  'Remove this service account?' => 'Удалить эту учетную запись службы?',
  'Testing connection…' => 'Проверка соединения...',
  'Connect each form to a specific Google Sheet tab' => 'Подключите каждую форму к определенной вкладке Google Sheet',
  'Connect each form to a specific Google Sheet tab — step by step' => 'Подключите каждую форму к определенной вкладке Google Sheet — шаг за шагом',
  'No service account connected.' => 'Нет подключенной учетной записи службы.',
  'Go to the Connections tab and drop a service account JSON key first.' => 'Перейдите на вкладку «Подключения» и сначала перетащите ключ JSON сервисного аккаунта.',
  'Last sync OK' => 'Последняя синхронизация ОК',
  'Last sync failed' => 'Последняя синхронизация не удалась',
  'Remove sync? The sheet stays safe.' => 'Удалить синхронизацию? Лист останется в безопасности.',
  'Yes, remove' => 'Да, удалить',
  'Remove this sync (your Google Sheet is not deleted)' => 'Удалите эту синхронизацию (ваша таблица Google не будет удалена)',
  'Existing Bindings' => 'Существующие привязки',
  'Delete All' => 'Удалить все',
  'New Binding' => 'Новая привязка',
  'Spreadsheet ID' => 'Идентификатор таблицы',
  'Tab' => 'tab',
  'Choose Sheet' => 'Выберите лист',
  'Columns & Fields' => 'Столбцы и поля',
  'Style & Save' => 'Стиль и сохранение',
  'Which form should send data to Google Sheets?' => 'Какая форма должна отправлять данные в Google Таблицы?',
  'Please select a form first.' => 'Сначала выберите форму.',
  'Service Account' => 'Служебный аккаунт',
  'Loading your spreadsheets…' => 'Загрузка таблиц...',
  'Click <strong>“Browse My Sheets”</strong> to list spreadsheets this service account can already access, or <strong>“Create New Sheet”</strong> to make a fresh one.' => 'Нажмите<strong>«Просмотреть мои таблицы»</strong>, чтобы просмотреть таблицы, к которым уже имеет доступ этот сервисный аккаунт, или<strong>«Создать новый лист»</strong>, чтобы создать новую.',
  '<strong>No spreadsheets are accessible to this service account yet.</strong> You have two options:' => '<strong>Для этого сервисного аккаунта пока недоступны электронные таблицы.</strong>У вас есть два варианта:',
  '<strong>Easiest:</strong> click <em>“Create New Sheet”</em> above — it is made for you and shared to your email automatically.' => '<strong>Самый простой:</strong>нажмите<em>«Создать новый лист»</em>выше — он создан для вас и автоматически отправлен на вашу электронную почту.',
  '<strong>Use an existing sheet:</strong> open it in Google Sheets &rarr; Share &rarr; paste' => '<strong>Использовать существующий лист:</strong>откройте его в Google Таблицах → Поделиться → Вставить',
  '&rarr; Editor, then click <em>Browse My Sheets</em> again.' => '→ Редактор, затем снова нажмите<em>«Просмотреть мои таблицы»</em>.',
  'the service account email' => 'электронная почта сервисного аккаунта',
  'Create a new spreadsheet' => 'Создайте новую таблицу',
  'New spreadsheet title (e.g. Contact form responses)' => 'Новое название таблицы (например, ответы в контактной форме)',
  'Your Google email — the sheet is shared here so you can open it' => 'Ваш адрес электронной почты Google — здесь размещен общий доступ к листу, поэтому вы можете его открыть',
  'Pre-filled from your saved email.' => 'Предварительно заполнено из сохраненного электронного письма.',
  'Leave empty only if you don’t need to open the sheet yourself.' => 'Оставьте пустым, только если вам не нужно открывать лист самостоятельно.',
  'Create Sheet' => 'Создать лист',
  'Creating…' => 'Создание...',
  'Creating spreadsheet…' => 'Создание таблицы...',
  'Sheet created and shared with your email. It’s selected below — click Next to finish.' => 'Лист создан и отправлен вам по электронной почте. Он выбран ниже — нажмите «Далее», чтобы закончить.',
  'Sheet created. Tip: add “Your Google email” on the Connections tab so new sheets are shared to you automatically.' => 'Лист создан. Совет: добавьте «Ваш адрес электронной почты Google» на вкладке «Подключения», чтобы вам автоматически предоставлялся доступ к новым таблицам.',
  'Open the new sheet' => 'Откройте новый лист',
  'Selected:' => 'Выбрано:',
  'Loading worksheet tabs…' => 'Загрузка вкладок листа...',
  'Worksheet Tab' => 'Вкладка «Рабочий лист»',
  'Or type a new tab name (created automatically)' => 'Или введите новое имя вкладки (создается автоматически)',
  'Browse My Sheets' => 'Просмотреть мои таблицы',
  'Create New Sheet' => 'Создать новый лист',
  'Choose or create a spreadsheet first' => 'Сначала выберите или создайте таблицу',
  'Please select a service account.' => 'Пожалуйста, выберите учетную запись службы.',
  'Please choose or create a spreadsheet first.' => 'Сначала выберите или создайте таблицу.',
  'Enable Sync for this Form' => 'Включить синхронизацию для этой формы',
  'Disable to pause without deleting the binding' => 'Отключить паузу без удаления привязки',
  'Reading this form’s fields…' => 'Чтение полей этой формы...',
  'We couldn’t read this form’s fields automatically, so column mapping isn’t available. Don’t worry — <strong>every submitted field will still be synced automatically</strong>, each in its own column, in submission order. The header row is created and kept up to date for you.' => 'Мы не смогли автоматически прочитать поля этой формы, поэтому сопоставление столбцов недоступно. Не волнуйтесь —<strong>каждое отправленное поле по-прежнему будет автоматически синхронизироваться</strong>, каждое в своем столбце, в порядке отправки. Строка заголовка создается и постоянно обновляется.',
  'Drag rows (or use ▲▼) to set the <strong>column order</strong>. Rename any <strong>header</strong>. Turn a field off to skip its column. The letter (A, B, C…) shows where each field lands.' => 'Перетащите строки (или используйте ▲▼), чтобы установить порядок столбцов<strong></strong>. Переименуйте любой заголовок<strong>в</strong>. Отключите поле, чтобы пропустить его столбец. Буква (A, B, C...) показывает, где находится каждое поле.',
  'Col' => 'Кол.',
  'Spreadsheet header' => 'Заголовок таблицы',
  'Order / On' => 'Заказать/включить',
  'Refresh fields from form' => 'Обновить поля формы',
  'Columns & Field Mapping' => 'Столбцы и сопоставление полей',
  'Submitted time' => 'Время отправки',
  'Submitted At' => 'Отправлено в',
  'Column header' => 'Заголовок столбца',
  'Include this field' => 'Включите это поле',
  '%d column will be written to the sheet.' . chr(0) . '%d columns will be written to the sheet.' => 'Столбец%dбудет записан на лист.' . chr(0) . 'Столбцы%dбудут записаны на лист.' . chr(0) . 'Столбцы%dбудут записаны на лист.',
  'Sheet Style' => 'Стиль листа',
  '(Google theme)' => '(тема Google)',
  'Pick a look for the sheet — colored header, frozen top row and alternating row colors (Google Sheets’ own styling). It’s applied automatically on the first sync, or apply it now.' => 'Выберите внешний вид листа — цветной заголовок, фиксированная верхняя строка и чередующиеся цвета строк (собственный стиль Google Sheets). Оно применяется автоматически при первой синхронизации или примените его сейчас.',
  'Apply style now' => 'Примените стиль сейчас',
  'Applying…' => 'Подача заявки...',
  'Optional — it also applies on the first submission.' => 'Необязательно — это также применяется при первой отправке.',
  'Spreadsheet:' => 'Таблица:',
  'Tab:' => 'Вкладка:',
  'Columns:' => 'Столбцы:',
  '%d mapped' => '%dсопоставлен',
  'all submitted fields (auto)' => 'все отправленные поля (авто)',
  'Style:' => 'Стиль:',
  'After saving, submit the form once to create the header row and confirm the first sync.' => 'После сохранения отправьте форму один раз, чтобы создать строку заголовка и подтвердить первую синхронизацию.',
  'Save Binding' => 'Сохранить привязку',
  'Please choose a spreadsheet first.' => 'Сначала выберите таблицу.',
  'Pick a style first — “None” leaves the sheet unstyled.' => 'Сначала выберите стиль: при выборе «Нет» лист останется без стиля.',
  'Style applied.' => 'Стиль применен.',
  'Please select a form.' => 'Пожалуйста, выберите форму.',
  'Please choose a spreadsheet.' => 'Пожалуйста, выберите таблицу.',
  'Binding saved.' => 'Привязка сохранена.',
  'Remove this binding? Syncing stops for this form. Your Google Sheet and its data are not deleted.' => 'Удалить эту привязку? Синхронизация останавливается для этой формы. Ваш Google Sheet и его данные не удаляются.',
  'Sync removed — your Google Sheet and its data are untouched.' => 'Синхронизация удалена — ваш Google Sheet и его данные не будут затронуты.',
  'Remove ALL %d binding? Syncing stops for every form. Your Google Sheets are not deleted.' . chr(0) . 'Remove ALL %d bindings? Syncing stops for every form. Your Google Sheets are not deleted.' => 'Удалить привязку ALL%d? Синхронизация останавливается для каждой формы. Ваши Google Таблицы не будут удалены.' . chr(0) . 'Удалить ВСЕ привязки%d? Синхронизация останавливается для каждой формы. Ваши Google Таблицы не будут удалены.' . chr(0) . 'Удалить ВСЕ привязки%d? Синхронизация останавливается для каждой формы. Ваши Google Таблицы не будут удалены.',
  'All bindings removed. Your Google Sheets are untouched.' => 'Все привязки удалены. Ваши Google Таблицы не тронуты.',
  'Help & Setup Guide' => 'Справка и руководство по установке',
  'Everything you need to connect forms to Google Sheets' => 'Все, что вам нужно для подключения форм к Google Таблицам',
  'Step-by-Step Setup' => 'Пошаговая настройка',
  'Create or Select a Project' => 'Создать или выбрать проект',
  'Open console.cloud.google.com and log in &rarr; click the Project dropdown (top-left) &rarr; New Project (or pick an existing one) &rarr; enter a name &rarr; Create' => 'Откройте console.cloud.google.com и войдите в систему → щелкните раскрывающийся список «Проект» (вверху слева) → «Новый проект» (или выберите существующий) → введите имя → «Создать», «en»]]',
  'Enable both Google APIs' => 'Включите оба API Google',
  'APIs &amp; Services &rarr; Library &rarr; enable <strong>Google Sheets API</strong> and <strong>Google Drive API</strong> (both are required — Drive lists and creates the files)' => 'API и службы → Библиотека → включить<strong>Google Sheets API</strong>и<strong>Google Drive API</strong>(оба обязательны — список дисков и создание файлов)',
  'Create a Service Account' => 'Создайте учетную запись службы',
  'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; enter a name &rarr; Done' => 'API и службы → Учетные данные → Создать учетные данные → Учетная запись службы → введите имя → Готово',
  'Create a JSON Key' => 'Создайте ключ JSON',
  'Open the service account &rarr; Keys tab &rarr; Add Key &rarr; Create New Key &rarr; choose JSON (file downloads automatically)' => 'Откройте учетную запись службы → вкладка «Ключи» → «Добавить ключ» → «Создать новый ключ» → выберите JSON (файл загружается автоматически)',
  'Drop the Key File' => 'Перетащите файл ключа',
  'Drag the downloaded file into the Connections tab — it is verified automatically and you’ll see a green “Connected” badge' => 'Перетащите загруженный файл на вкладку «Подключения» — он будет проверен автоматически, и вы увидите зеленый значок «Подключено».',
  'Add Your Google Email' => 'Добавьте свой адрес электронной почты Google',
  'On the Connections tab, fill in “Your Google email” and Save — sheets the plugin creates are then shared to you so they appear in your own Drive' => 'На вкладке «Подключения» заполните «Ваш адрес электронной почты Google» и «Сохранить» — листы, созданные плагином, затем будут доступны вам и появятся на вашем собственном Диске.',
  'Bind a Form (create a sheet)' => 'Привязать форму (создать лист)',
  'Form Bindings &rarr; pick a form &rarr; <strong>Create New Sheet</strong> &rarr; Save. No manual sharing needed — this is the easiest path' => 'Привязки формы → выберите форму →<strong>Создать новый лист</strong>→ Сохранить. Не требуется предоставлять общий доступ вручную — это самый простой путь',
  '…or use an existing sheet' => '...или используйте существующий лист',
  'Prefer your own sheet? Open it &rarr; Share &rarr; paste the service account email (copy button on its card) &rarr; Editor &rarr; then Browse My Sheets in the wizard' => 'Предпочитаете свой собственный лист? Откройте его → Поделиться → вставьте адрес электронной почты сервисного аккаунта (кнопка «копировать» на его карточке) → Редактор → затем «Просмотрите мои таблицы» в мастере», \'en\']]',
  'I created a sheet — where did it go?' => 'Я создал лист — куда он делся?',
  'Service accounts create files in their own hidden Drive. Add “Your Google email” on the Connections tab and the plugin shares every new sheet to you automatically — it then appears under “Shared with me” in your Google Drive. Each sheet also has an “Open” link right in this dashboard.' => 'Служебные аккаунты создают файлы на своем скрытом диске. Добавьте «Ваш адрес электронной почты Google» на вкладке «Подключения», и плагин автоматически предоставит вам каждый новый лист — затем он появится в разделе «Доступно мне» на вашем Google Диске. На каждом листе также есть ссылка «Открыть» прямо на этой панели управления.',
  'Why don’t I see my existing sheet in the picker?' => 'Почему я не вижу существующий лист в средстве выбора?',
  'It must be shared with the service account’s email first: open the sheet &rarr; Share &rarr; paste the email (use the copy button on the connection card) &rarr; set Editor &rarr; Share. Then click “Browse My Sheets” again.' => 'Сначала его необходимо открыть для электронной почты сервисного аккаунта: откройте лист → Поделиться → вставьте письмо (используйте кнопку копирования на карточке подключения) → установите Редактор → Поделиться. Затем снова нажмите «Просмотреть мои таблицы».',
  'Test result: Google API is not enabled.' => 'Результат проверки: Google API не включен.',
  'Open Google Cloud Console for the same project &rarr; APIs &amp; Services &rarr; Library, and enable BOTH “Google Sheets API” and “Google Drive API”. Wait a minute, then retest.' => 'Откройте консоль Google Cloud для того же проекта → API и сервисы → Библиотека и включите ОБА «API Google Таблиц» и «API Google Диска». Подождите минуту, затем повторите тестирование.',
  'Test result: Access/Permission denied' => 'Результат проверки: доступ/разрешение отклонены',
  'The service account can authenticate but can’t reach that specific spreadsheet. Re-share the sheet with the service account email as Editor, or create a new sheet instead.' => 'Учетная запись службы может пройти аутентификацию, но не может получить доступ к этой конкретной таблице. Повторно поделитесь листом с адресом электронной почты сервисного аккаунта в качестве редактора или вместо этого создайте новый лист.',
  'OpenSSL is required.' => 'Требуется OpenSSL.',
  'The server is missing the PHP OpenSSL extension used to sign the secure Google request. Ask your host to enable it — no plugin setting can replace it.' => 'На сервере отсутствует расширение PHP OpenSSL, используемое для подписи безопасного запроса Google. Попросите вашего хостера включить его — никакие настройки плагина не смогут его заменить.',
  'Can I connect more than one service account?' => 'Могу ли я подключить более одной учетной записи службы?',
  'Yes — drop as many JSON keys as you like in the Connections tab and pick which one each form binding should use.' => 'Да — добавьте столько ключей JSON, сколько хотите, на вкладку «Соединения» и выберите, какой из них должна использовать каждая привязка формы.',
  'Does the connection expire?' => 'Срок действия соединения истек?',
  'No. The integration runs entirely on the server using your JSON key — there’s no browser session or login to expire.' => 'Нет. Интеграция полностью выполняется на сервере с использованием вашего ключа JSON — нет сеанса браузера или входа в систему, срок действия которого истекает.',
  'Can I choose which field goes to which column?' => 'Могу ли я выбрать, какое поле относится к какому столбцу?',
  'Yes. In the binding wizard’s <strong>Columns &amp; Fields</strong> step, drag rows (or use ▲▼) to set the order, rename each column header, and toggle any field off to skip it. The A/B/C badge shows exactly where each field lands.' => 'Да. На шаге<strong>Columns & Fields</strong>мастера привязки перетащите строки (или используйте ▲▼), чтобы установить порядок, переименуйте каждый заголовок столбца и отключите любое поле, чтобы пропустить его. Значок A/B/C показывает, где именно находится каждое поле.',
  'Can I style the sheet automatically?' => 'Можно ли автоматически стилизовать лист?',
  'Yes. The <strong>Style &amp; Save</strong> step offers Google-Sheets themes (colored header, frozen top row, alternating row colors). Pick one and it’s applied on the first sync, or click “Apply style now”.' => 'Да. Шаг<strong>«Стиль и сохранение»</strong>предлагает темы Google-Таблиц (цветной заголовок, фиксированный верхний ряд, чередующиеся цвета строк). Выберите один из них, и он будет применен при первой синхронизации, или нажмите «Применить стиль сейчас».',
  'What if my form fields change later?' => 'Что, если поля моей формы изменятся позже?',
  'New fields are added automatically. In mapped mode, open the Columns step and click “Refresh fields from form” to pull them into the mapping; in “All Form Fields” mode they appear as new columns on the next submission.' => 'Новые поля добавляются автоматически. В режиме сопоставления откройте шаг «Столбцы» и нажмите «Обновить поля из формы», чтобы перенести их в сопоставление; в режиме «Все поля формы» они отображаются как новые столбцы при следующей отправке.',
  'What if the tab doesn’t exist yet?' => 'Что делать, если вкладка еще не существует?',
  'It is created automatically the first time a submission is synced.' => 'Он создается автоматически при первой синхронизации отправки.',
  'Google Sheet Sync Logs' => 'Журналы синхронизации Google Таблиц',
  'Latest submissions sent to Google Sheets, success or failure' => 'Последние отправленные материалы в Google Таблицы: успешные или неудачные.',
  'Log cleared.' => 'Журнал очищен.',
  'Clear Log' => 'Очистить журнал',
  'Clear all logs?' => 'Очистить все журналы?',
  'No sync activity yet.' => 'Синхронизация пока не выполнена.',
  'Spreadsheet' => 'Таблица',
  'Synced' => 'синхронизировано',
  'None (plain)' => 'Нет (обычный)',
  'Minimal' => 'Минимальный',
  'Slate' => 'Сланец',
  'Sunset' => 'Закат',
  'Grape' => 'Виноград',
  '%s is currently unavailable.' => '%sв настоящее время недоступен.',
  'disabled in php.ini: %s' => 'отключено в php.ini:%s',
  'not provided by PHP or its required extension: %s' => 'не предоставляется PHP или его необходимым расширением:%s',
  '%1$s cannot run because required PHP functions are unavailable (%2$s). Ask your hosting provider to enable the required PHP extension or remove the listed functions from disable_functions in php.ini.' => '%1$sне может быть запущен, поскольку необходимые функции PHP недоступны (%2$s). Попросите своего хостинг-провайдера включить необходимое расширение PHP или удалить перечисленные функции из Disabled_functions в php.ini.',
  'This add-on is not included in Flux Forms.' => 'Это дополнение не включено в Flux Forms.',
  'Error: server (%s) responded with an invalid request. responded code : %s ' => 'Ошибка: сервер (%s) ответил неверным запросом. код ответа:%s',
  'Your Easy Form Builder Pro subscription has expired, so this add-on cannot be downloaded.' => 'Срок действия вашей подписки на Easy Form Builder Pro истек, поэтому загрузить это дополнение невозможно.',
  'Something went wrong, please refresh the page.' => 'Что-то пошло не так, обновите страницу.',
  'The response attachment could not be verified. Please attach the file again.' => 'Не удалось проверить вложение ответа. Пожалуйста, прикрепите файл еще раз.',
  'You do not have permission to update these settings.' => 'У вас нет разрешения на обновление этих настроек.',
  'Please enter a valid admin email address.' => 'Пожалуйста, введите действительный адрес электронной почты администратора.',
  'You do not have permission to complete setup.' => 'У вас недостаточно прав для завершения установки.',
  'Invalid email address' => 'Неверный адрес электронной почты',
  'Invalid sender email' => 'Неверный адрес электронной почты отправителя',
  'The sender email address is not valid.' => 'Адрес электронной почты отправителя недействителен.',
  'Email tester service error' => 'Ошибка службы проверки электронной почты',
  'Could not start email test.' => 'Не удалось запустить проверку электронной почты.',
  'Invalid service response' => 'Неверный ответ службы',
  'The email tester service returned an invalid response.' => 'Служба проверки электронной почты вернула неверный ответ.',
  'The message never left your website: WordPress reported an error while trying to send it. This is the one case where the fix really is on the WordPress or hosting side - usually an SMTP plugin, or PHP mail disabled by the host.' => 'Сообщение так и не покинуло ваш сайт: WordPress сообщил об ошибке при попытке его отправки. Это единственный случай, когда исправление действительно происходит на стороне WordPress или хостинга — обычно это плагин SMTP или почта PHP, отключенная хостом.',
  'WordPress could not send the test email. The message never left your website, so nothing was delivered.' => 'WordPress не удалось отправить тестовое письмо. Сообщение так и не покинуло ваш сайт, поэтому ничего не было доставлено.',
  'Email test is waiting for delivery confirmation' => 'Проверка электронной почты ожидает подтверждения доставки',
  'WordPress sent the test email. Flux Forms is waiting for the delivery result before marking email as ready.' => 'WordPress отправил тестовое письмо. Flux Forms ожидает результата доставки, прежде чем пометить электронное письмо как готовое.',
  'WordPress accepted and sent the test email. Waiting for it to arrive.' => 'WordPress принял и отправил тестовое письмо. Ждем его прибытия.',
  'The email tester service returned an invalid JSON response.' => 'Служба проверки электронной почты вернула неверный ответ в формате JSON.',
  'The email tester service could not start the test.' => 'Службе тестирования электронной почты не удалось запустить тест.',
  'Invalid test hash' => 'Неверный хэш теста',
  'The email test hash is not valid.' => 'Тестовый хеш электронной почты недействителен.',
  'Your site could not connect' => 'Ваш сайт не смог подключиться',
  'No connection could be opened from your site to our mail testing service. This is usually outbound traffic blocked by your server or its network - some hosts block connections to other countries - rather than a problem with the service. Your hosting provider can confirm it.' => 'Не удалось установить соединение с вашего сайта с нашей службой тестирования почты. Обычно это исходящий трафик, заблокированный вашим сервером или его сетью (некоторые хосты блокируют соединения с другими странами), а не проблема со службой. Ваш хостинг-провайдер может это подтвердить.',
  'Service error' => 'Ошибка сервиса',
  'The email tester service could not return the result.' => 'Служба проверки электронной почты не может вернуть результат.',
  'The message never left your website. WordPress reported an error while sending, so nothing could be delivered.' => 'Сообщение никогда не покидало ваш сайт. WordPress сообщил об ошибке при отправке, поэтому доставить ничего не удалось.',
  'The email was sent, but it never arrived' => 'Письмо было отправлено, но так и не пришло',
  'WordPress sent the message successfully, so your site and this plugin did their part. It was lost, delayed or rejected after leaving WordPress - usually the receiving side treated it as spam, or your host never delivered it from the outbound queue.' => 'WordPress успешно отправил сообщение, поэтому ваш сайт и этот плагин внесли свой вклад. Оно было потеряно, задержано или отклонено после выхода из WordPress — обычно принимающая сторона считала его спамом, или ваш хост не доставил его из исходящей очереди.',
  'Email test failed' => 'Проверка электронной почты не удалась',
  'The email server test could not verify email capability.' => 'Тестирование сервера электронной почты не смогло проверить возможности электронной почты.',
  'Email capability verified' => 'Возможность электронной почты проверена',
  'Server confirmed ability to send emails.' => 'Сервер подтвердил возможность отправлять электронную почту.',
  'Your emails are being delivered to spam' => 'Ваши письма попадают в спам',
  'WordPress sent the test email, but delivery has not been confirmed yet.' => 'WordPress отправил тестовое письмо, но доставка еще не подтверждена.',
  'Email delivery failed: %s' => 'Не удалось доставить электронное письмо:%s',
  'No file was received. Please choose a file and try again.' => 'Файл не получен. Пожалуйста, выберите файл и повторите попытку.',
  'The file could not be read. Please try attaching it again.' => 'Файл не может быть прочитан. Пожалуйста, попробуйте прикрепить его еще раз.',
  'Enable the Email Notification Feature' => 'Включите функцию уведомления по электронной почте',
  'To receive email notifications from your forms, verify your email server by following these steps:' => 'Чтобы получать уведомления по электронной почте из ваших форм, подтвердите свой почтовый сервер, выполнив следующие действия:',
  'Go to the <a href="%s" style="font-weight:600;">Flux Forms Panel</a>' => 'Перейдите на панель<a href="%s" style="font-weight:600;">Flux Forms</a>',
  'Click Settings from the top menu' => 'Нажмите «Настройки» в верхнем меню',
  'Select the Email Settings tab' => 'Выберите вкладку «Настройки электронной почты».',
  'Click "Check Email Server" and wait for the test to finish' => 'Нажмите «Проверить сервер электронной почты» и дождитесь завершения теста.',
  'If the score is above 70 — enable the "This site can send emails" switch and save' => 'Если оценка выше 70 — включите переключатель «Этот сайт может отправлять электронные письма» и сохраните',
  'Otherwise, follow the instructions shown in the test results' => 'В противном случае следуйте инструкциям, указанным в результатах теста.',
  '%s notification' => ' Уведомление%s',
  'Disabling this feature may affect the proper functionality of Flux Forms. If you plan to use the %s feature, please ensure it is enabled.' => 'Отключение этой функции может повлиять на правильную работу Flux Forms. Если вы планируете использовать функцию%s, убедитесь, что она включена.',
  'Email system is working properly.' => 'Система электронной почты работает правильно.',
  'Your server is able to send emails using the default PHP mail system.' => 'Ваш сервер может отправлять электронные письма, используя почтовую систему PHP по умолчанию.',
  'Email system is not available.' => 'Система электронной почты недоступна.',
  'The PHP mail() function is missing. Your server cannot send emails.' => 'Функция PHP mail() отсутствует. Ваш сервер не может отправлять электронную почту.',
  'Email sending is blocked by server settings.' => 'Отправка электронной почты заблокирована настройками сервера.',
  'The mail() function is disabled in your server PHP configuration (php.ini).' => 'Функция mail() отключена в конфигурации PHP вашего сервера (php.ini).',
  'WordPress mail function not found.' => 'Функция почты WordPress не найдена.',
  'The wp_mail() function is missing or not available. WordPress email features may be broken.' => 'Функция wp_mail() отсутствует или недоступна. Функции электронной почты WordPress могут быть неработоспособны.',
  'No email handler configured.' => 'Обработчик электронной почты не настроен.',
  'Your server has no SMTP host or sendmail path set. Emails may not be delivered.' => 'На вашем сервере не указан хост SMTP или путь отправки почты. Письма могут не доставляться.',
  'Test email could not be sent.' => 'Не удалось отправить тестовое письмо.',
  'It seems that your WordPress site could not send a test email. To manually test your email system, go to Flux Forms > Settings > Email Settings tab and click the "Check Email Server" button.' => 'Похоже, что ваш сайт WordPress не смог отправить тестовое письмо. Чтобы вручную протестировать систему электронной почты, перейдите на вкладку Flux Forms > Настройки > Настройки электронной почты и нажмите кнопку «Проверить сервер электронной почты».',
  'Invalid email address.' => 'Неверный адрес электронной почты.',
  'Please enter a valid admin email address before testing email delivery.' => 'Перед проверкой доставки электронной почты введите действительный адрес электронной почты администратора.',
  'Invalid sender email.' => 'Неверный адрес электронной почты отправителя.',
  'The sender email address is not valid. Please check your email settings.' => 'Адрес электронной почты отправителя недействителен. Пожалуйста, проверьте настройки электронной почты.',
  'Email tester service error.' => 'Ошибка службы тестера электронной почты.',
  'Flux Forms could not start the email delivery test. Please try again later.' => 'Flux Forms не удалось запустить тест доставки электронной почты. Пожалуйста, повторите попытку позже.',
  'Invalid email tester response.' => 'Неверный ответ тестера электронной почты.',
  'Invalid email test.' => 'Неверный тест электронной почты.',
  'The email test identifier is invalid. Please start a new test.' => 'Идентификатор теста электронной почты недействителен. Пожалуйста, начните новый тест.',
  'Email tester connection error.' => 'Ошибка подключения тестера электронной почты.',
  'Flux Forms could not connect to the email tester service.' => 'Flux Forms не удалось подключиться к службе проверки электронной почты.',
  'Email delivery test failed.' => 'Проверка доставки электронной почты не удалась.',
  'Your emails are arriving in the spam folder.' => 'Ваши письма попадают в папку «Спам».',
  'The test message was delivered, but its deliverability score is too low to rely on. Sending through SMTP and adding SPF and DKIM records for your domain is what fixes this.' => 'Тестовое сообщение было доставлено, но его показатель доставляемости слишком низок, чтобы на него можно было положиться. Это решается отправкой через SMTP и добавлением записей SPF и DKIM для вашего домена.',
  'Email delivery test is pending.' => 'Ожидается проверка доставки электронной почты.',
  'Email Issue' => 'Проблема с электронной почтой',
  'Flux Forms Email Warning:' => 'Предупреждение по электронной почте Flux Forms:',
  'Plan data is missing.' => 'Данные плана отсутствуют.',
  'Invalid plan data format.' => 'Неверный формат данных плана.',
  'Invalid plan type.' => 'Неверный тип плана.',
  'Please confirm this plan downgrade before continuing.' => 'Пожалуйста, подтвердите переход на более ранний план, прежде чем продолжить.',
  'Free plan activated - no additional features.' => 'Бесплатный план активирован — дополнительных функций нет.',
  'Free Plus plan activated with enhanced features.' => 'Активирован план Free Plus с расширенными функциями.',
  'Pro plan activated with existing activation code.' => 'План Pro активирован с использованием существующего кода активации.',
  'Redirecting to Pro plan purchase page.' => 'Перенаправление на страницу покупки плана Pro.',
  'Plan "%s" has been successfully processed.' => 'План «%s» успешно обработан.',
  'Addon Installation Issue' => 'Проблема с установкой аддона',
  'Technical Details' => 'Технические детали',
  'Checked %s' => 'Проверено%s',
  'System Ready' => 'Система готова',
  'Checking add-on installation capabilities&hellip;' => 'Проверка возможности установки дополнений...',
  'This check runs once after plugin activation. Please refresh the page in a few moments.' => 'Эта проверка выполняется один раз после активации плагина. Пожалуйста, обновите страницу через несколько минут.',
  'Some add-ons need a PHP server change' => 'Некоторые дополнения требуют смены сервера PHP',
  'Flux Forms has safely paused each affected active add-on, so the rest of the plugin can continue working.' => 'Flux Forms безопасно приостановил работу каждого затронутого активного дополнения, чтобы остальная часть плагина могла продолжить работу.',
  '(currently enabled and paused)' => '(в настоящее время включено и приостановлено)',
  '(not enabled)' => '(не включено)',
  'disabled in php.ini:' => 'отключено в php.ini:',
  'not provided by PHP or its required extension:' => 'не предусмотрено PHP или его необходимым расширением:',
  'This usually means the needed PHP extension is not installed, or the function is listed in disable_functions in php.ini. Please ask your hosting provider to enable it, then refresh this page.' => 'Обычно это означает, что необходимое расширение PHP не установлено или функция указана в отключении_функций в php.ini. Попросите вашего хостинг-провайдера включить эту функцию, а затем обновите эту страницу.',
  'If you are seeing this message, it is likely for one of these reasons: If you have a caching plugin installed, its settings may need to be reviewed.' => 'Если вы видите это сообщение, скорее всего, это происходит по одной из следующих причин: Если у вас установлен плагин кеширования, возможно, необходимо просмотреть его настройки.',
  'Please also ensure that you have a stable internet connection and try again.' => 'Также убедитесь, что у вас стабильное подключение к Интернету, и повторите попытку.',
  'Built with %sYT Form%s by %sWordPress form plugin by whitestudio.team%s' => 'Создано с помощью%sYT Form%sот%sПлагин формы WordPress от whitestudio.team%s',
  'Free WordPress form plugin' => 'Бесплатный плагин форм WordPress',
  'Powered by %1$sYT Form%2$s . %3$sbest Form plugin for Wordpress%4$s.' => 'При поддержке%1$sФорма YT%2$s.%3$sлучший плагин форм для Wordpress%4$s.',
  'Flux Forms WordPress Plugin' => 'Плагин Flux Forms для WordPress',
  'This form requires a payment method. Please add one or change the form type.' => 'Для этой формы требуется способ оплаты. Добавьте одну или измените тип формы.',
  'Error Monitor' => 'Монитор ошибок',
  'WordPress Core' => 'Ядро WordPress',
  'Line' => 'Линия',
  'No errors detected' => 'Ошибок не обнаружено',
  'These errors may interfere with forms built using Flux Forms.' => 'Эти ошибки могут помешать работе форм, созданных с использованием Flux Forms.',
  'This panel is only visible to site administrators.' => 'Эта панель видна только администраторам сайта.',
  'jQuery Dependency Issue' => 'jQuery Проблема с зависимостями',
  'jQuery is not properly loaded or available. AJAX and interactive form features may not work correctly.' => 'jQuery неправильно загружен или недоступен. Функции AJAX и интерактивные формы могут работать неправильно.',
  'WhiteStudio.team' => 'WhiteStudio.team',
  'EFB' => 'EFB',
  'Flux Forms is a free and powerful WordPress form builder plugin for creating contact forms, payment forms, surveys, registration forms, multi-step forms, file upload forms, electronic signature forms, and audio, video, and screen recording forms, with conditional logic, email notifications, integrations, entry management, and advanced spam protection.' => 'Flux Forms — это бесплатный и мощный плагин для создания форм WordPress для создания контактных форм, форм оплаты, опросов, форм регистрации, многошаговых форм, форм загрузки файлов, форм электронной подписи, а также форм аудио, видео и записи экрана с условной логикой, уведомлениями по электронной почте, интеграцией, управлением записями и расширенной защитой от спама.',
  'WordPress Form Builder Plugin' => 'Плагин WordPress Form Builder',
  'WordPress 5.0 or later; PHP 7.0 or later' => 'WordPress 5.0 или новее; PHP 7.0 или более поздней версии',
  'Flux Forms Documentation' => 'Документация по формам Flux',
  'Drag-and-Drop WordPress Form Builder' => 'Конструктор форм WordPress с возможностью перетаскивания',
  'Unlimited Forms and Form Entries' => 'Неограниченное количество форм и записей в формах',
  'Responsive and RTL-Friendly Forms' => 'Адаптивные и дружественные к RTL формы',
  'Contact and Inquiry Forms' => 'Формы обратной связи и запросов',
  'Support and Feedback Forms with Message Tracking' => 'Формы поддержки и обратной связи с отслеживанием сообщений',
  'Survey and Poll Forms with Visual Results' => 'Формы опросов и опросов с визуальными результатами',
  'Stripe and PayPal Payment Forms' => 'Формы оплаты Stripe и PayPal',
  'WordPress Login and Registration Forms' => 'Формы входа и регистрации WordPress',
  'File Upload Forms' => 'Формы загрузки файлов',
  'Audio Recording Forms' => 'Формы аудиозаписи',
  'Video Recording Forms' => 'Формы видеозаписи',
  'Screen Recording Forms with Optional Microphone Audio' => 'Формы записи экрана с дополнительным звуком через микрофон',
  'Private and Restricted-Access Forms' => 'Частные формы и формы с ограниченным доступом',
  'Multi-Step Forms' => 'Многошаговые формы',
  'Smart Forms with Conditional Logic' => 'Умные формы с условной логикой',
