  'WPBakery form plugin' => 'Плагин формы WPBakery',
  'Some plugin files are missing, so the plugin stopped loading to keep your site running. Please reinstall Flux Forms from the Plugins page — your forms, messages, and settings are kept.' => 'Некоторые файлы плагина отсутствуют, поэтому плагин перестал загружаться, чтобы ваш сайт продолжал работать. Пожалуйста, переустановите Flux Forms со страницы Плагины — ваши формы, сообщения и настройки сохранятся.',
  'Missing files:' => 'Отсутствующие файлы:',
  'Select a form to display from the dropdown below.' => 'Выберите форму для отображения из раскрывающегося списка ниже.',
  'Selected Form:' => 'Выбранная форма:',
  'Form will be displayed here on the frontend.' => 'Форма будет отображаться здесь, во внешнем интерфейсе.',
