  '📍 Confirmation Code Finder (Tracking Form)' => '📍 Поиск кода подтверждения (форма отслеживания)',
  'Choose a form to display. The tracking form allows users to find submissions by confirmation code.' => 'Выберите форму для отображения. Форма отслеживания позволяет пользователям находить отправленные материалы по коду подтверждения.',
  'Show Form Title' => 'Показать заголовок формы',
  'Container' => 'Контейнер',
