  'Select a form from the widget settings panel.' => 'Выберите форму на панели настроек виджета.',
  '👈 Use the sidebar to choose a form' => '👈 Используйте боковую панель, чтобы выбрать форму',
  'Selected Form ID:' => 'Выбранный идентификатор формы:',
  'The form will appear here on the frontend.' => 'Форма появится здесь, в интерфейсе.',
  'Display an Flux Forms form' => 'Отображение формы Flux Forms',
  'Display the form name as a heading above the form.' => 'Отображение имени формы в виде заголовка над формой.',
  'Extra Class Name' => 'Дополнительное имя класса',
  'Add custom CSS classes for styling.' => 'Добавьте пользовательские классы CSS для стилизации.',
  'Design' => 'Дизайн',
  'CSS' => 'CSS',
  'Select a form from the element settings.' => 'Выберите форму в настройках элемента.',
  '✏️ Click to edit and choose a form' => '✏️ Нажмите, чтобы отредактировать и выберите форму',
  'Add forms created with Flux Forms' => 'Добавить формы, созданные с помощью Flux Forms',
  'Display Flux Forms forms on your page' => 'Отображение форм Flux Forms на вашей странице',
  'Choose the form you want to display' => 'Выберите форму, которую хотите отобразить',
  'Please select a form from element settings' => 'Пожалуйста, выберите форму в настройках элемента',
  'Form: %s (ID: %s)' => 'Форма:%s(ID:%s)',
  '📍 Confirmation Code Finder (Tracking)' => '📍 Поиск кода подтверждения (отслеживание)',
  '🎨 Flux Forms' => '🎨 Формы потока',
  'Add Flux Forms forms to your page' => 'Добавьте формы Flux Forms на свою страницу',
  'Select Form:' => 'Выберите форму:',
  'Custom Title (optional):' => 'Пользовательский заголовок (необязательно):',
  'Shortcode:' => 'Короткий код:',
  'Run the email check' => 'Запустите проверку электронной почты',
  'The last delivery check scored %s out of 100. Your messages do leave the site, but most mailboxes will file them as spam, so the people filling in your forms will not see them. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.' => 'Последняя проверка доставки получила оценку%sиз 100. Ваши сообщения покидают сайт, но большинство почтовых ящиков воспринимают их как спам, поэтому люди, заполняющие ваши формы, не увидят их. Это решается отправкой через службу SMTP и добавлением записей SPF и DKIM для вашего домена.',
  'The last delivery check found that your messages do leave the site, but mailboxes file them as spam. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.' => 'Последняя проверка доставки показала, что ваши сообщения покидают сайт, но почтовые ящики фиксируют их как спам. Это решается отправкой через службу SMTP и добавлением записей SPF и DKIM для вашего домена.',
  'Your form emails are going to the spam folder' => 'Ваши электронные письма попадают в папку «Спам».',
  'Your form emails are sent, but they are not arriving' => 'Ваши электронные письма отправлены, но не доходят',
  'WordPress sent the last test message successfully, so your site and this plugin did their part - it was lost, delayed or rejected after leaving WordPress. Usually the receiving mailbox treated it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.' => 'WordPress успешно отправил последнее тестовое сообщение, поэтому ваш сайт и этот плагин сделали свое дело — оно было потеряно, задержано или отклонено после выхода из WordPress. Обычно принимающий почтовый ящик воспринимал его как спам, или ваш хост никогда не доставлял его из исходящей очереди. Это решается отправкой через службу SMTP с записями SPF и DKIM для вашего домена.',
  'WordPress cannot send your form emails' => 'WordPress не может отправлять электронные письма с формой',
  'The last check could not even hand a message to your mail server: WordPress reported an error while sending, so nothing left the site. An SMTP plugin, or asking your host whether PHP mail is disabled, is where to start.' => 'Последняя проверка даже не смогла передать сообщение на ваш почтовый сервер: WordPress сообщил об ошибке при отправке, поэтому с сайта ничего не ушло. Плагин SMTP или запрос вашего хоста, отключена ли почта PHP, — это то, с чего следует начать.',
  'Your form emails are not being delivered' => 'Ваши электронные письма не доставляются',
  'The last delivery check could not get a message through, so nothing your forms send is reaching anybody. A hosting server usually sends mail without a trusted signature; sending through an SMTP service is the standard fix.' => 'Последней проверке доставки не удалось доставить сообщение, поэтому никакие отправленные вами формы никому не доходят. Хостинг-сервер обычно отправляет почту без доверенной подписи; отправка через службу SMTP является стандартным решением.',
  'Once Weekly (Flux Forms)' => 'Один раз в неделю (формы Flux)',
  'The weekly email delivery test completed successfully.' => 'Еженедельный тест доставки электронной почты успешно завершен.',
  'The weekly email delivery test found an email delivery problem.' => 'Еженедельная проверка доставки электронной почты выявила проблему с доставкой электронной почты.',
  'The main WordPress administrator email address is not valid.' => 'Основной адрес электронной почты администратора WordPress недействителен.',
  'Could not start the email delivery test.' => 'Не удалось запустить проверку доставки электронной почты.',
  'WordPress sent the automated test email and is waiting for it to arrive.' => 'WordPress отправил автоматическое тестовое письмо и ожидает его прибытия.',
  'WordPress could not send the automated test email. The message never left this website.' => 'WordPress не удалось отправить автоматическое тестовое письмо. Сообщение никогда не покидало этот сайт.',
  'The email delivery test timed out before confirmation was received.' => 'Прежде чем было получено подтверждение, время ожидания проверки доставки электронной почты истекло.',
  'Weekly Flux Forms report for %s' => 'Еженедельный отчет Flux Forms для%s',
  'Here is your weekly snapshot for %s.' => 'Вот ваш еженедельный снимок%s.',
  'Report generated %s' => 'Отчет создан%s',
  'Detailed analysis' => 'Детальный анализ',
  'Emails failed' => 'Электронная почта не отправлена',
  'You can turn these reports off in Flux Forms settings.' => 'Вы можете отключить эти отчеты в настройках Flux Forms.',
  'The test email was delivered, but its deliverability score is only %1$s out of 100 (below %2$s), so the emails your forms send are very likely to be rejected or filtered as spam.' => 'Тестовое электронное письмо было доставлено, но его показатель доставляемости составляет только%1$sиз 100 (ниже%2$s), поэтому электронные письма, отправляемые вашими формами, с большой вероятностью будут отклонены или отфильтрованы как спам.',
  'Run the email check so you can be sure the messages your forms send are actually reaching people. The check sends a real message through the new WhiteStudio delivery service and reports back what arrived.' => 'Запустите проверку электронной почты, чтобы быть уверенным, что сообщения, отправляемые вашими формами, действительно доходят до людей. Проверка отправляет реальное сообщение через новую службу доставки WhiteStudio и сообщает о том, что пришло.',
  'Read the guide to sending email through SMTP' => 'Прочитайте руководство по отправке электронной почты через SMTP',
  'Delivery has not been scored yet' => 'Доставка еще не оценена',
  'WordPress sent your email, but it never arrived' => 'WordPress отправил ваше письмо, но оно так и не пришло',
  'WordPress could not send your email' => 'WordPress не удалось отправить ваше письмо',
  'We could not confirm your emails are being delivered' => 'Мы не смогли подтвердить доставку ваших писем.',
  'out of 100' => 'из 100',
  'Your email delivery is healthy' => 'Доставка электронной почты работает нормально',
  'Your emails are likely going to spam' => 'Ваши письма, скорее всего, попадут в спам',
  'Your emails are not reaching anybody' => 'Ваши письма никому не доходят',
  'grade %s' => 'оценка%s',
  'What you should do' => 'Что вам следует делать',
  'A hosting server usually sends mail without a trusted signature, which is what pushes your form emails into the spam folder or stops them arriving at all. The standard fix is to send through an SMTP service.' => 'Хостинг-сервер обычно отправляет почту без доверенной подписи, что приводит к тому, что ваши электронные письма попадают в папку со спамом или вообще останавливаются. Стандартное решение — отправка через службу SMTP.',
  'Install an SMTP plugin and enter the details of your email service.' => 'Установите плагин SMTP и введите данные своей почтовой службы.',
  'Add the SPF and DKIM records to your domain settings.' => 'Добавьте записи SPF и DKIM в настройки вашего домена.',
  'Run the email check again until the score is above %s.' => 'Запустите проверку электронной почты еще раз, пока оценка не превысит%s.',
  'You have %1$s forms: %2$s active and %3$s inactive.' => 'У вас есть формы%1$s:%2$sактивна и%3$sнеактивна.',
  'Renew Flux Forms Pro' => 'Обновить формы Flux Pro',
  'Get more from Flux Forms Pro' => 'Получите больше от Flux Forms Pro',
  'Renew your subscription to restore all Pro features and add-ons.' => 'Обновите подписку, чтобы восстановить все функции и дополнения Pro.',
  'Unlock premium add-ons, unlimited features and priority support for your forms.' => 'Разблокируйте надстройки премиум-класса, неограниченные функции и приоритетную поддержку ваших форм.',
  'Renew Pro' => 'Обновить Pro',
  'Email delivery is working' => 'Доставка электронной почты работает',
  'The automated Flux Forms email delivery test completed successfully.' => 'Автоматическая проверка доставки электронной почты Flux Forms завершена успешно.',
  'You can attach up to %1$d file here. Please wait about %2$d minutes before trying again.' . chr(0) . 'You can attach up to %1$d files here. Please wait about %2$d minutes before trying again.' => 'Здесь вы можете прикрепить файл%1$d. Прежде чем повторить попытку, подождите около%2$dминут.' . chr(0) . 'Здесь вы можете прикрепить файлы до%1$d. Прежде чем повторить попытку, подождите около%2$dминут.' . chr(0) . 'Здесь вы можете прикрепить файлы до%1$d. Прежде чем повторить попытку, подождите около%2$dминут.',
  'This file is too large. The maximum size for this field is %s.' => 'Этот файл слишком велик. Максимальный размер этого поля —%s.',
  'This file type is not accepted here. Please attach one of the file types listed on the field.' => 'Этот тип файла здесь не принимается. Прикрепите один из типов файлов, перечисленных в поле.',
  'This file appears to be empty. Please choose a different file.' => 'Этот файл кажется пустым. Пожалуйста, выберите другой файл.',
  'The uploaded file could not be verified. Please attach it again.' => 'Загруженный файл не удалось проверить. Пожалуйста, прикрепите его еще раз.',
  'X-WP-Nonce header is missing' => 'Заголовок X-WP-Nonce отсутствует',
  'Your form session has expired. Please reload the page.' => 'Срок вашего сеанса формы истек. Пожалуйста, перезагрузите страницу.',
  'Form ID:' => 'Идентификатор формы:',
  'The form will be displayed on the frontend.' => 'Форма будет отображена во внешнем интерфейсе.',
  'This link uses an older format. For improved security, new email notifications include updated links.' => 'Эта ссылка использует старый формат. Для повышения безопасности новые уведомления по электронной почте включают обновленные ссылки.',
  'It seems that you are the admin of this form. Please log in and try again.' => 'Похоже, что вы являетесь администратором этой формы. Пожалуйста, войдите в систему и повторите попытку.',
  'Flux Forms couldn\'t locate the form settings. Please check your settings or contact support for assistance.' => 'Flux Forms не удалось найти настройки формы. Пожалуйста, проверьте настройки или обратитесь в службу поддержки за помощью.',
  'Y/m/d \\a\\t g:ia' => 'Y/m/d \\a\\t g:ia',
  'Too many attempts. Please wait a few minutes and try again.' => 'Слишком много попыток. Пожалуйста, подождите несколько минут и повторите попытку.',
  'The recording upload could not be verified. Please record it again and retry.' => 'Не удалось проверить загрузку записи. Пожалуйста, запишите его еще раз и повторите попытку.',
  'This recording format is not supported. Please record it again.' => 'Этот формат записи не поддерживается. Пожалуйста, запишите это еще раз.',
  'The server could not verify the recording format. Please contact the site administrator.' => 'Серверу не удалось проверить формат записи. Пожалуйста, свяжитесь с администратором сайта.',
  'The recording format could not be verified. Please record it again.' => 'Не удалось проверить формат записи. Пожалуйста, запишите это еще раз.',
  'The server could not verify the recording duration. Please record it again and try uploading.' => 'Серверу не удалось проверить продолжительность записи. Пожалуйста, запишите его еще раз и попробуйте загрузить.',
  'The server could not store the recording. Please try again or contact the site administrator.' => 'Серверу не удалось сохранить запись. Пожалуйста, попробуйте еще раз или обратитесь к администратору сайта.',
  'The recording request could not be verified. Please retry.' => 'Запрос на запись не может быть проверен. Пожалуйста, повторите попытку.',
  'The upload request could not be verified. Please try again.' => 'Запрос на загрузку не удалось проверить. Пожалуйста, попробуйте еще раз.',
  'The upload field could not be verified. Please refresh the form and try again.' => 'Не удалось проверить поле загрузки. Пожалуйста, обновите форму и повторите попытку.',
  'The response box could not be verified. Reopen the conversation and try again.' => 'Не удалось проверить поле ответа. Откройте беседу снова и повторите попытку.',
  'The response attachment could not be secured. Please try again.' => 'Не удалось защитить вложение ответа. Пожалуйста, попробуйте еще раз.',
  'Not allowed to respond to this message.' => 'Не разрешено отвечать на это сообщение.',
  'Payment Intent ID is missing' => 'Идентификатор платежного намерения отсутствует',
  'persiaPayment' => 'persiaPayment',
  'The Email Address Is Not Valid' => 'Адрес электронной почты недействителен',
  'The Username Must Contain Only Letters, Numbers And Lowercase letters' => 'Имя пользователя должно содержать только буквы, цифры и строчные буквы',
  'The Username Must Contain At Least 3 Characters.' => 'Имя пользователя должно содержать не менее 3 символов.',
  'The Password Must Contain At Least 8 Characters!' => 'Пароль должен содержать не менее 8 символов!',
  'The Password Must Contain At Least 1 Number!' => 'Пароль должен содержать хотя бы 1 цифру!',
  'The Password Must Contain At Least 1 Capital Letter!' => 'Пароль должен содержать хотя бы 1 заглавную букву!',
  'The Password Must Contain At Least 1 Lowercase Letter!' => 'Пароль должен содержать хотя бы 1 строчную букву!',
  'Audio recording' => 'Аудиозапись',
  'Video recording' => 'Видеозапись',
  'Screen recording' => 'Запись экрана',
  'Form Preview' => 'Предварительный просмотр формы',
  'Create New Password' => 'Создайте новый пароль',
  'Create a secure password for your account' => 'Создайте надежный пароль для своей учетной записи',
  'New Password' => 'Новый пароль',
  'Enter your new password' => 'Введите новый пароль',
  'Set Password' => 'Установить пароль',
  'Error! Please try again later.' => 'Ошибка! Пожалуйста, повторите попытку позже.',
  'Password has been changed successfully!' => 'Пароль успешно изменен!',
  'Invalid payment selection. Please review your choices and try again. If the problem persists, contact the site administrator.' => 'Неверный выбор платежа. Пожалуйста, проверьте свой выбор и повторите попытку. Если проблема не устранена, обратитесь к администратору сайта.',
  'If your emails are not being delivered, try using an SMTP plugin. For more information, %1$s click here %2$s or contact our %3$s support team %4$s.' => 'Если ваши электронные письма не доставляются, попробуйте использовать плагин SMTP. Для получения дополнительной информации%1$sнажмите здесь%2$sили свяжитесь с нашей службой поддержки%3$s%4$s.',
  'View Messages' => 'Просмотр сообщений',
  'Hello!' => 'Привет!',
  'New Message' => 'Новое сообщение',
  'New message received' => 'Получено новое сообщение',
  'We received your message' => 'Мы получили ваше сообщение',
  'This email was sent automatically. Please do not reply.' => 'Это письмо было отправлено автоматически. Пожалуйста, не отвечайте.',
  'Built with %1$sYT Form%2$s by %3$sWhiteStudio.team%4$s' => 'Создано с помощью%1$sYT Form%2$sот%3$sWhiteStudio.team%4$s',
  'Weekly Flux Forms report' => 'Еженедельный отчет Flux Forms',
  'Pro features are paused' => 'Функции Pro приостановлены',
  'Congratulations! Email System Working' => 'Поздравляем! Система электронной почты работает',
  'Your server has successfully sent this test email. The email delivery system is properly configured and functioning.' => 'Ваш сервер успешно отправил это тестовое письмо. Система доставки электронной почты правильно настроена и функционирует.',
  'Email Delivery Tips' => 'Советы по доставке электронной почты',
  'Form submitted successfully without tracking.' => 'Форма успешно отправлена без отслеживания.',
  'Your message has been received and recorded successfully.' => 'Ваше сообщение получено и успешно записано.',
  'Reset Password' => 'Сбросить пароль',
  'Or copy and paste this link:' => 'Или скопируйте и вставьте эту ссылку:',
  'If you did not request this, you can safely ignore it.' => 'Если вы этого не запрашивали, можете смело игнорировать это.',
  'Hi' => 'Привет',
  'You have requested to reset your password.' => 'Вы запросили сброс пароля.',
  'Click the button below to set a new password. This link will be valid for 24 hours.' => 'Нажмите кнопку ниже, чтобы установить новый пароль. Эта ссылка будет действительна в течение 24 часов.',
  'Verify Email' => 'Подтвердить адрес электронной почты',
  'Your account has been successfully created!' => 'Ваша учетная запись успешно создана!',
  'Please verify your email address by clicking the button below. This activation link will be valid for 24 hours.' => 'Подтвердите свой адрес электронной почты, нажав кнопку ниже. Эта ссылка активации будет действительна в течение 24 часов.',
  'A new user has registered on your website.' => 'На вашем сайте зарегистрировался новый пользователь.',
  'The user has been sent a verification email to confirm their account.' => 'Пользователю было отправлено электронное письмо с подтверждением для подтверждения его учетной записи.',
  'This is an alert message regarding a SID validation error. This issue may have occurred due to a plugin conflict or an unauthorized attempt to access the website.' => 'Это предупреждение об ошибке проверки SID. Эта проблема могла возникнуть из-за конфликта плагинов или несанкционированной попытки доступа к веб-сайту.',
  'If you receive this email multiple times, it could indicate a recurring issue.' => 'Если вы получили это письмо несколько раз, это может указывать на повторяющуюся проблему.',
  'Please contact our support team for assistance.' => 'Пожалуйста, обратитесь в нашу службу поддержки за помощью.',
  'One or more of the plugins listed below—typically related to caching or security—might be triggering this issue. For troubleshooting, temporarily deactivate them and test your site.' => 'Один или несколько перечисленных ниже плагинов, обычно связанных с кэшированием или безопасностью, могут вызывать эту проблему. Для устранения неполадок временно отключите их и протестируйте свой сайт.',
  'SID Validation Error' => 'Ошибка проверки SID',
  'Please select a form to display.' => 'Пожалуйста, выберите форму для отображения.',
  'Sürükle-bırak form oluşturucu: çok adımlı formlar, Stripe ödemeleri, koşullu mantık, dashboard, otomasyonlar ve Flux Certificates entegrasyonu. Easy Form Builder (WhiteStudio, GPL) tabanlı fork.' => 'Конструктор форм с возможностью перетаскивания: многошаговые формы, платежи Stripe, условная логика, панель мониторинга, автоматизация и интеграция сертификатов Flux. Форк на основе Easy Form Builder (WhiteStudio, GPL).',
  'The currency of this form is not supported.' => 'Валюта этой формы не поддерживается.',
  'The Stripe secret key is not configured.' => 'Секретный ключ Stripe не настроен.',
  'Could not connect to Stripe: %s' => 'Не удалось подключиться к Stripe:%s',
  'Stripe API error (HTTP %d).' => 'Ошибка API-интерфейса Stripe (HTTP%d).',
  'Cannot install addons:%s' => 'Невозможно установить дополнения:%s',
  '%scomplete' => '%sзавершен',
  'Help us speak your language! Translate Flux Forms on the%1$sWordPress.org translation portal%2$sand make it accessible to your community.' => 'Помогите нам говорить на вашем языке! Переведите формы Flux на портале переводов WordPress.org%1$s%2$sи сделайте их доступными для вашего сообщества.',
  'Type your reply...' => 'Введите ответ...',
  '%swidth' => ' Ширина%s',
  '%sLabel Position' => '%sПоложение метки',
  '%sLabel size' => '%sРазмер этикетки',
  '%sLabel | Align' => ' Ярлык%s| Выровнять',
  '%sDescription | Align' => '%sОписание | Выровнять',
  '%sButtons | Align' => ' Кнопки%s| Выровнять',
  '%sChecked Color' => '%sПроверенный цвет',
  'Switch%s' => 'Переключить%s',
  '%scolor' => ' Цвет%s',
  'height' => 'высота',
  'KeepPro' => 'KeepPro',
  'Checking email delivery...' => 'Проверка доставки электронной почты...',
  'A test email was sent. Waiting for delivery confirmation...' => 'Отправлено тестовое письмо. Ожидание подтверждения доставки...',
  'Your test email was delivered, but its deliverability score is only%1$sout of 100 (below%2$s). The emails your forms send will most likely be filtered as spam. Set up SMTP and run the check again.' => 'Ваше тестовое письмо было доставлено, но его показатель доставляемости составляет всего%1$sиз 100 (ниже%2$s). Письма, отправляемые вашими формами, скорее всего, будут отфильтрованы как спам. Настройте SMTP и запустите проверку еще раз.',
  'Custom%sMessage' => 'Пользовательское сообщение%s',
  'Leave empty to use default%s' => 'Оставьте пустым, чтобы использовать%sпо умолчанию ',
  'If your language translation is not available yet, translate it and get a%3$slifetime discount! Contribute via the%1$sWordPress.org translation portal%2$s.' => 'Если ваш языковой перевод еще недоступен, переведите его и получите пожизненную скидку%3$s! Внесите свой вклад через портал переводов%1$sWordPress.org%2$s.',
  'Adds your form activity totals – forms, views and submissions – to the weekly email your site sends the main administrator. These totals are read on your own site and are never sent to WhiteStudio.' => 'Добавляет общие сведения о вашей активности в форме (формы, просмотры и отправки) в еженедельное электронное письмо, которое ваш сайт отправляет главному администратору. Эти итоговые данные считываются на вашем сайте и никогда не отправляются в WhiteStudio.',
  'Upgrade to Pro for just%1$s%2$s%3$s/year and get access to powerful features, including advanced form fields, payment integrations, conditional logic, multi-step forms, file uploads, Security & Spam Protection, and priority support.%4$sView Pro Features%5$s' => 'Обновите версию Pro всего за%1$s%2$s%3$sв год и получите доступ к мощным функциям, включая расширенные поля форм, интеграцию платежей, условную логику, многошаговые формы, загрузку файлов, безопасность и защиту от спама, а также приоритетную поддержку.%4$sВозможности View Pro%5$s',
  'You can create up to%1$s%2$son your current plan. Upgrade to Pro for unlimited access.' => 'В текущем плане вы можете создать до%1$s%2$s. Обновите версию до версии Pro, чтобы получить неограниченный доступ.',
  'A value is written to this field while another rule hides or disables it — hidden and disabled fields are not saved with the entry.' => 'В это поле записывается значение, в то время как другое правило скрывает или отключает его — скрытые и отключенные поля не сохраняются вместе с записью.',
  'Message...' => 'Сообщение...',
  'hide' => 'скрыть',
  'Uploading recording...' => 'Загрузка записи...',
  'Your hosting accepts uploads up to%sMB.' => 'Ваш хостинг принимает загрузки размером до%sМБ.',
  'This is larger than the hosting upload limit (%sMB); uploads will fail.' => 'Это превышает лимит загрузки хостинга (%sМБ); загрузка не удастся.',
  '%sFailures' => ' Сбои%s',
  '%sError Log' => ' Журнал ошибок%s',
  '%sDetails' => '%sПодробности',
  'The confirmation code for this message is%s. By clicking the button below, you will be able to track messages and view received responses. If needed, you can also send a new reply.' => 'Код подтверждения для этого сообщения:%s. Нажав кнопку ниже, вы сможете отслеживать сообщения и просматривать полученные ответы. При необходимости вы также можете отправить новый ответ.',
  'To explore the full functionality and settings of Flux Forms, including email configurations, form creation options, and other features, simply delve into our%1$sdocumentation%2$s.' => 'Чтобы изучить все функциональные возможности и настройки Flux Forms, включая настройки электронной почты, параметры создания форм и другие функции, просто воспользуйтесь нашей документацией%1$s%2$s.',
  'Test emails may land in your spam folder. If emails are not delivered, this is usually related to your hosting or email server configuration.server settings%1$sLearn how to fix email delivery issues%2$sor%3$scontact Flux Forms support%4$s.' => 'Тестовые письма могут попасть в папку со спамом. Если электронные письма не доставляются, это обычно связано с конфигурацией вашего хостинга или почтового сервера. Настройки сервера%1$sУзнайте, как устранить проблемы с доставкой электронной почты%2$sили%3$sОбратитесь в службу поддержки Flux Forms%4$s.',
  'I have read and agree to%1$sthe terms and conditions%2$s' => 'Я прочитал%1$sусловия использования%2$sи согласен с ними ',
  'Valid formats:%s' => 'Действительные форматы:%s',
  'The%1$spages are currently unavailable. It looks like another plugin is causing a conflict with%1$s. To fix this issue,%2$scontact%1$ssupport%3$sfor assistance or try disabling your plugins one at a time to identify the one causing the conflict.' => 'Страницы%1$sв настоящее время недоступны. Похоже, другой плагин вызывает конфликт с%1$s. Чтобы устранить эту проблему,%2$sобратитесь в службу поддержки%1$s%3$sза помощью или попробуйте отключить плагины по одному, чтобы определить тот, который вызывает конфликт.',
  '%scopied!' => '%sскопировано!',
  'Enable%s' => 'Включить%s',
  'Upload the%sfile' => 'Загрузите файл%s',
  'The%shas been successfully completed' => '%sуспешно завершен',
  '%snot found' => '%sне найден',
  '%sLocation' => '%sМестоположение',
  'The%shave been deleted.' => '%sудален.',
  'The%sfield must be correctly filled out to proceed.' => 'Для продолжения поле%sдолжно быть правильно заполнено.',
  'Learn more about%sor watch the video tutorial.' => 'Узнайте больше о%sили посмотрите видеоруководство.',
  'Learn more%s' => 'Подробнее%s',
  'Your request was completed successfully.%1$s%2$s' => 'Ваш запрос успешно выполнен.%1$s%2$s',
  'To use%1$sfeatures in your forms, you need to get your%2$skeys.' => 'Чтобы использовать функции%1$sв своих формах, вам необходимо получить ключи%2$s.',
  'Go to the add-ons page in the Flux Forms plugin, install the%sadd-on, and try again.' => 'Перейдите на страницу надстроек в плагине Flux Forms, установите надстройку%sи повторите попытку.',
  'To create a payment form to collect online payments, install a payment add-on such as the%sAdd-on first.' => 'Чтобы создать платежную форму для сбора онлайн-платежей, сначала установите надстройку для оплаты, например надстройку%s.',
  'The%splugin may interfere with Flux Forms form functionality. If you encounter any issues with the forms, disable caching for the Flux Forms plugin in the%ssettings.' => 'Плагин%sможет мешать работе форм Flux Forms. Если у вас возникли проблемы с формами, отключите кеширование для плагина Flux Forms в настройках%s.',
  'Got it, don\'t show it again' => 'Понятно, больше не показывать',
  'The value of the%1$sfield does not match the pattern and must be at least%2$scharacters.' => 'Значение поля%1$sне соответствует шаблону и должно содержать не менее символов%2$s.',
  'The value of the%1$sfield does not match the pattern and must be at most%2$scharacters.' => 'Значение поля%1$sне соответствует шаблону и должно содержать не более символов%2$s.',
  'Please enter valid value for the%sfield.' => 'Пожалуйста, введите допустимое значение в поле%s.',
  '%slist' => ' Список%s',
  'The uploaded file exceeds the allowable limit of%sMB.' => 'Загруженный файл превышает допустимый лимит%sМБ.',
  'The uploaded file is below the required minimum size of%sMB.' => 'Размер загруженного файла меньше требуемого минимального размера%sМБ.',
  'Review the entered values in the%stab. This message appeared because an error was detected.' => 'Проверьте введенные значения на вкладке%s. Это сообщение появилось, потому что была обнаружена ошибка.',
  'We are sorry, the booking time for the%soption has expired. Please choose from the other available options.' => 'К сожалению, время бронирования опции%sистекло. Пожалуйста, выберите один из других доступных вариантов.',
  'We are sorry, the%soption is currently at full capacity. Please choose from the other available options.' => 'Приносим извинения, опция%sв настоящее время загружена на полную мощность. Пожалуйста, выберите один из других доступных вариантов.',
  '%sPayment Add-on' => '%sПлатежное дополнение',
  'The%sadd-on for Flux Forms enables you to integrate your WordPress site with%sfor payment processing, donations, and online orders.' => 'Дополнение%sдля Flux Forms позволяет интегрировать ваш сайт WordPress с%sдля обработки платежей, пожертвований и онлайн-заказов.',
  'Found%s%sfor: "%s"' => 'Найдено%s%sдля: "%s"',
  'Found%1$s%2$sfor' => 'Найдено%1$s%2$sдля',
  '%sDay' => '%sДень',
  '%sDays' => '%sдней',
  'Choose the style for the%s.' => 'Выберите стиль для%s.',
  '%1$s+%2$s' => '%1$s+%2$s',
  '%1$s%2$s&%3$s' => '%1$s%2$sи%3$s',
  '%sunsaved changes' => '%sнесохраненные изменения',
  'Your text here...' => 'Ваш текст здесь...',
  'Dismiss%s' => 'Отклонить%s',
  'The test email was delivered with a deliverability score of%1$sout of 100. Under%2$s, most mailboxes file messages in the spam folder, so the people filling in your forms may never see them.' => 'Тестовое электронное письмо было доставлено с оценкой доставляемости%1$sиз 100. При использовании%2$sбольшинство почтовых ящиков отправляют сообщения в папку «Спам», поэтому люди, заполняющие ваши формы, могут их никогда не увидеть.',
  'Your email server is working. A detailed HTML report has been sent to%s.' => 'Ваш почтовый сервер работает. Подробный отчет в формате HTML отправлен на адрес%s.',
  'A complete email health report — including your spam score, deliverability details, and recommendations — will be sent to%swithin the next few minutes.' => 'Полный отчет о состоянии электронной почты, включая оценку спама, сведения о доставляемости и рекомендации, будет отправлен на адрес%sв течение следующих нескольких минут.',
  'This form\'s email notification feature is enabled, but email delivery has not been verified and the latest spam score is%s/100. The form was saved, but admin notification emails may not reach you until SMTP/email delivery is fixed.' => 'Функция уведомления по электронной почте в этой форме включена, но доставка электронной почты не проверена, а последняя оценка спама —%s/100. Форма была сохранена, но электронные письма с уведомлениями администратора могут не дойти до вас, пока доставка SMTP/электронной почты не будет исправлена.',
  '%sof 5 steps done' => '%sиз 5 шагов выполнено',
  'Step%sof 5' => 'Шаг%sиз 5',
  'Score:%s' => 'Оценка:%s',
  'Waiting for the test email to arrive...' => 'Ожидание тестового письма...',
  'Still checking — please wait a moment...' => 'Проверяем — пожалуйста, подождите...',
  'Starting email delivery test...' => 'Начинаем тест доставки электронной почты...',
  'WordPress accepted and sent the message. Waiting for it to arrive...' => 'WordPress принял и отправил сообщение. Ждем его прибытия...',
  'Connection error. Please refresh the page and try again. (Code:%s)' => 'Ошибка подключения. Пожалуйста, обновите страницу и повторите попытку. (Код:%s)',
  'turkey' => 'индейка',
  'bug report' => 'отчет об ошибке',
  'kosher' => 'кошерный',
  'banner' => 'баннер',
  'Installing add-ons...' => 'Установка дополнений...',
  'Error: server (%s) responded with an invalid request. responded code:%s' => 'Ошибка: сервер (%s) ответил неверным запросом. код ответа:%s',
  'Cannot install add-ons of Flux Forms because the plugin is not able to connect to the%sserver' => 'Невозможно установить дополнения Flux Forms, поскольку плагин не может подключиться к серверу%s',
  'To fix this, sign in to your%s, download the Add-ons Handler plugin from the Downloads section, then install and activate it. After that, activate the add-ons you need from the Add-ons Handler plugin.' => 'Чтобы это исправить, войдите в свою учетную запись%s, загрузите плагин Add-ons Handler из раздела «Загрузки», затем установите и активируйте его. После этого активируйте нужные вам надстройки с помощью плагина Add-ons Handler.',
  'Your server could not reach%1$s, so the add-on could not be downloaded. This is almost always a firewall on your hosting blocking the outgoing request, not a problem with your licence. To install add-ons without any download at all, sign in at%2$sand download the Flux Forms Add-ons Handler plugin, then install it like any other plugin. It contains every add-on your licence covers.' => 'Ваш сервер не смог связаться с%1$s, поэтому дополнение не удалось загрузить. Почти всегда это брандмауэр на вашем хостинге, блокирующий исходящий запрос, а не проблема с вашей лицензией. Чтобы установить надстройки вообще без какой-либо загрузки, войдите в систему на%2$sи загрузите плагин Flux Forms Add-ons Handler, а затем установите его, как любой другой плагин. Он содержит все дополнения, на которые распространяется ваша лицензия.',
  'If you would rather fix the connection, ask your hosting provider why outgoing requests from%sare being blocked.' => 'Если вы предпочитаете исправить соединение, узнайте у своего хостинг-провайдера, почему блокируются исходящие запросы от%s.',
  'Add-on affected:%s' => 'Затронуто дополнение:%s',
  'Action needed: Flux Forms Pro is paused on%s' => 'Требуется действие: Flux Forms Pro приостановлен на%s',
  'Flux Forms could not confirm your Pro licence for%1$sdays in a row, so the Pro features on%2$sare paused for now.' => 'Flux Forms не может подтвердить вашу лицензию Pro в течение%1$sдней подряд, поэтому функции Pro на%2$sна данный момент приостановлены.',
  'Your forms, entries and settings are untouched, every free feature keeps working, and your activation code is still stored — nothing was deleted.' => 'Ваши формы, записи и настройки не тронуты, все бесплатные функции продолжают работать, а ваш код активации по-прежнему сохраняется — ничего не было удалено.',
  'Open%1$sYT Form → Settings%2$sand press%1$sSave%2$s. That checks the licence again straight away; if the connection is back, Pro switches on within a minute.' => 'Откройте форму%1$sYT → Настройки%2$sи нажмите%1$sСохранить%2$s. Это немедленно проверяет лицензию еще раз; если соединение восстановится, Pro включится через минуту.',
  'Still paused? Ask your hosting provider to allow outgoing HTTPS connections to%s— a firewall, proxy or regional block is the usual cause — then repeat step 1.' => 'Все еще приостановлено? Попросите своего хостинг-провайдера разрешить исходящие HTTPS-соединения к%s(обычной причиной является брандмауэр, прокси-сервер или региональная блокировка), а затем повторите шаг 1.',
  'If your subscription has expired, or you moved this website to a new domain,%1$srenew or re-activate your licence%2$sand paste the new code into Settings.' => 'Если срок вашей подписки истек или вы переместили этот веб-сайт в новый домен,%1$sпродлите или повторно активируйте лицензию%2$sи вставьте новый код в настройки.',
  'grace period' => 'льготный период',
  'Still stuck? Send the details above to%1$sour support team%2$sand we will take it from there.' => 'Все еще застрял? Отправьте приведенную выше информацию%1$sв нашу службу поддержки%2$s, и мы примем меры.',
  'Your website could not reach the licence server — almost always a network, firewall or DNS restriction on the hosting side.' => 'Ваш веб-сайт не может связаться с сервером лицензий — почти всегда из-за ограничений сети, брандмауэра или DNS на стороне хостинга.',
  'The licence server’s answer arrived damaged, usually because a security plugin, proxy or CDN changed it on the way.' => 'Ответ сервера лицензий пришел поврежденным, обычно из-за того, что плагин безопасности, прокси-сервер или CDN изменили его по пути.',
  'Your Easy Form Builder Pro subscription has expired. To continue using the%sadd-on and all Pro features, please renew your subscription.' => 'Срок действия вашей подписки на Easy Form Builder Pro истек. Чтобы продолжить использование дополнения%sи всех функций версии Pro, продлите подписку.',
  'The%sadd-on is a Pro feature. Please upgrade to Flux Forms Pro to access this functionality.' => 'Дополнение%s— это функция Pro. Пожалуйста, обновите Flux Forms Pro, чтобы получить доступ к этой функции.',
  'Your Easy Form Builder Pro subscription has expired. To continue enjoying all Pro features and keep your forms running,%1$sRenew your subscription now.%2$s' => 'Срок действия вашей подписки на Easy Form Builder Pro истек. Чтобы и дальше пользоваться всеми функциями версии Pro и поддерживать работоспособность форм,%1$sпродлите подписку прямо сейчас.%2$s',
  'The latest%dpayments are shown.' => 'Отображаются последние платежи%d.',
  '%ssettings' => ' Настройки%s',
  'Flux Forms replaces%s, which has been deactivated. Your forms, entries and settings stay in place. You can delete the old plugin.' => 'Flux Forms заменяет%s, который был деактивирован. Ваши формы, записи и настройки останутся на месте. Вы можете удалить старый плагин.',
  'Updating amount...' => 'Обновление суммы...',
  '%sunread in total' => '%sвсего непрочитано',
  'Recorded since%s' => 'Записано с%s',
  'Responses per view since%s' => 'Ответов на просмотр с момента%s',
  '%spaid' => '%sоплачен',
  'Also%s' => 'Также%s',
  'vs previous%ddays' => 'по сравнению с предыдущими днями%d',
  '%spayments' => '%sплатежи',
  '%sother forms' => '%sдругие формы',
  'Flux Donate is not active; Flux Forms takes payments itself with%s.' => 'Flux Donate не активен; Flux Forms сам принимает платежи с помощью%s.',
  'Flux Donate is not active and the Stripe keys are missing:%dpayment form shows "Online payment is unavailable".' . chr(0) . 'Flux Donate is not active and the Stripe keys are missing:%dpayment forms show "Online payment is unavailable".' => 'Flux Donate не активен и ключи Stripe отсутствуют: форма оплаты%dпоказывает «Онлайн-платеж недоступен».' . chr(0) . 'Flux Donate не активен, а ключи Stripe отсутствуют: в формах оплаты%dотображается сообщение «Онлайн-платеж недоступен».' . chr(0) . 'Flux Donate не активен, а ключи Stripe отсутствуют: в формах оплаты%dотображается сообщение «Онлайн-платеж недоступен».',
  'Version%sis active; certificate automations can run.' => 'Версия%sактивна; автоматизация сертификатов может работать.',
  'Version%1$sis active; certificate automations need%2$sor later.' => 'Версия%1$sактивна; для автоматизации сертификатов требуется%2$sили более поздняя версия.',
  'Not active, but%dactive automation creates or sends certificates; it will fail.' . chr(0) . 'Not active, but%dactive automations create or send certificates; they will fail.' => 'Не активно, но%dактивная автоматизация создает или отправляет сертификаты; это потерпит неудачу.' . chr(0) . 'Не активно, но активные средства автоматизации%dсоздают или отправляют сертификаты; они потерпят неудачу.' . chr(0) . 'Не активно, но активные средства автоматизации%dсоздают или отправляют сертификаты; они потерпят неудачу.',
  '%dautomation is on.' . chr(0) . '%dautomations are on.' => ' Автоматизация%dвключена.' . chr(0) . ' Автоматизация%dвключена.' . chr(0) . ' Автоматизация%dвключена.',
  '%drun failed in the last 7 days; see the run log.' . chr(0) . '%druns failed in the last 7 days; see the run log.' => ' За последние 7 дней не удалось выполнить%d; см. журнал запусков.' . chr(0) . ' За последние 7 дней не удалось выполнить%d; см. журнал запусков.' . chr(0) . ' За последние 7 дней не удалось выполнить%d; см. журнал запусков.',
  'Keys are set;%dform uses reCAPTCHA.%dforms use reCAPTCHA.' => 'Ключи установлены; Форма%dиспользует reCAPTCHA. В формах%dиспользуется reCAPTCHA.',
  '%dform has reCAPTCHA on but the site key or secret key is missing; the form is not shown.' . chr(0) . '%dforms have reCAPTCHA on but the site key or secret key is missing; they are not shown.' => ' В форме%dвключена reCAPTCHA, но отсутствует ключ сайта или секретный ключ; форма не отображается.' . chr(0) . ' В формах%dвключена reCAPTCHA, но отсутствует ключ сайта или секретный ключ; они не показаны.' . chr(0) . ' В формах%dвключена reCAPTCHA, но отсутствует ключ сайта или секретный ключ; они не показаны.',
  'The uploads folder is not available:%s' => 'Папка загрузок недоступна:%s',
  'Not writable:%s. File fields in forms cannot save uploads; ask the host to fix the folder permissions.' => 'Недоступно для записи:%s. Поля файлов в формах не могут сохранять загрузки; попросите хоста исправить права доступа к папке.',
  'Donation form:%s' => 'Форма пожертвования:%s',
  'The latest%druns are kept.' => 'Сохраняются последние запуски%d.',
  'Preparing your certificate...' => 'Подготовка сертификата...',
  'Certificate%1$sfor%2$s(%3$s)' => 'Сертификат%1$sдля%2$s(%3$s)',
  'Queued:%s' => 'В очереди:%s',
  'New submission:%s' => 'Новая запись:%s',
  'Search elements...' => 'Поиск элементов...',
  'Create a bot using%s' => 'Создайте бота с помощью%s',
  'Find your Chat ID using%s' => 'Найдите свой идентификатор чата, используя%s',
  'Enter your test message here...' => 'Введите здесь тестовое сообщение...',
  'Type your message here...' => 'Введите здесь свое сообщение...',
  'Protection is paused: required PHP functions are disabled on this server:%s. Ask your host to remove them from the disable_functions line in php.ini. Your forms keep working without protection until then.' => 'Защита приостановлена: на этом сервере отключены необходимые функции PHP:%s. Попросите вашего хостера удалить их из строки Disable_functions в php.ini. До этого момента ваши формы будут работать без защиты.',
  'Security log export is unavailable because this server has disabled a required PHP function:%s. Ask your hosting provider to enable it.' => 'Экспорт журнала безопасности недоступен, поскольку на этом сервере отключена необходимая функция PHP:%s. Попросите вашего хостинг-провайдера включить эту функцию.',
  'Security log export is unavailable because this server has disabled required PHP functions:%s. Ask your hosting provider to enable them.' => 'Экспорт журнала безопасности недоступен, поскольку на этом сервере отключены необходимые функции PHP:%s. Попросите вашего хостинг-провайдера включить их.',
  'Testing connection...' => 'Проверка соединения...',
  'Saving...' => 'Сохранение...',
  'API returned error:%d' => 'API возвратил ошибку:%d',
  'Loading...' => 'Загрузка...',
  'PayPal%s' => 'PayPal%s',
  'Stripe%s' => 'Полоса%s',
  'Manage and track all%stransactions. View payment details, process refunds, and export records.' => 'Управляйте и отслеживайте все транзакции%s. Просматривайте сведения о платежах, обрабатывайте возвраты и экспортируйте записи.',
  '%dservice account connected' . chr(0) . '%dservice accounts connected' => 'Учетная запись службы%dподключена' . chr(0) . ' Подключены сервисные учетные записи%d' . chr(0) . ' Подключены сервисные учетные записи%d',
  'Google Sheet sync cannot work until it is enabled. Please ask your host to enable the%sPHP extension, then reload this page.' => 'Синхронизация Google Sheet не может работать, пока она не включена. Попросите вашего хостера включить расширение PHP%s, а затем перезагрузите эту страницу.',
  'To sync an<strong>existing</strong>sheet: open it in Google Sheets →<strong>Share</strong>→ paste the email above → set role to<strong>Editor</strong>. To create a<strong>new</strong>sheet, just use Form Bindings — no sharing needed.' => 'Чтобы синхронизировать существующий лист<strong></strong>: откройте его в Google Sheets →<strong>Поделиться</strong>→ вставьте адрес электронной почты выше → установите роль<strong>Editor</strong>. Чтобы создать новый лист<strong></strong>, просто используйте привязки форм — общий доступ не требуется.',
  'Any sheet the plugin<strong>creates</strong>is automatically shared to this address, so it appears in your own Google Drive under “Shared with me.” Without it, new sheets stay hidden inside the service account.' => 'Любой лист, который плагин<strong>создает</strong>, автоматически передается по этому адресу, поэтому он появляется на вашем Google Диске в разделе «Доступно мне». Без этого новые листы останутся скрытыми внутри учетной записи службы.',
  'Go to<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ Project dropdown (top-left) → New Project → name it → Create' => 'Перейдите на<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ раскрывающийся список «Проект» (вверху слева) → «Новый проект» → назовите его → «Создать».',
  'APIs & Services → Library → enable<strong>Google Sheets API</strong><em>and</em><strong>Google Drive API</strong>' => 'API и службы → Библиотека → включить<strong>Google Sheets API</strong><em>и</em><strong>Google Drive API</strong>',
  'APIs & Services → Credentials → Create Credentials → Service Account → name it → Done' => 'API и службы → Учетные данные → Создать учетные данные → Учетная запись службы → назовите ее → Готово',
  'Open the service account → Keys tab → Add Key → Create New Key → JSON (downloads automatically)' => 'Откройте сервисный аккаунт → вкладка «Ключи» → «Добавить ключ» → «Создать новый ключ» → JSON (загружается автоматически)',
  'Add<strong>Your Google email</strong>above so created sheets land in your Drive' => 'Добавьте<strong>свой адрес электронной почты Google</strong>, указанный выше, чтобы созданные листы попадали на ваш Диск.',
  'Could not read file:%s' => 'Не удалось прочитать файл:%s',
  'Connecting service account...' => 'Подключение сервисного аккаунта...',
  'Saved. New sheets created by the plugin will be shared to%sautomatically.' => 'Сохранено. Новые листы, созданные плагином, будут автоматически доступны%s.',
  'tab' => 'tab',
  'Loading your spreadsheets...' => 'Загрузка таблиц...',
  'Click<strong>“Browse My Sheets”</strong>to list spreadsheets this service account can already access, or<strong>“Create New Sheet”</strong>to make a fresh one.' => 'Нажмите<strong>«Просмотреть мои таблицы»</strong>, чтобы просмотреть таблицы, к которым уже имеет доступ этот сервисный аккаунт, или<strong>«Создать новый лист»</strong>, чтобы создать новую.',
  '<strong>No spreadsheets are accessible to this service account yet.</strong>You have two options:' => '<strong>Для этого сервисного аккаунта пока недоступны электронные таблицы.</strong>У вас есть два варианта:',
  '<strong>Easiest:</strong>click<em>“Create New Sheet”</em>above — it is made for you and shared to your email automatically.' => '<strong>Самый простой:</strong>нажмите<em>«Создать новый лист»</em>выше — он создан для вас и автоматически отправлен на вашу электронную почту.',
  '<strong>Use an existing sheet:</strong>open it in Google Sheets → Share → paste' => '<strong>Использовать существующий лист:</strong>откройте его в Google Таблицах → Поделиться → Вставить',
  '→ Editor, then click<em>Browse My Sheets</em>again.' => '→ Редактор, затем снова нажмите<em>«Просмотреть мои таблицы»</em>.',
  'Creating...' => 'Создание...',
  'Creating spreadsheet...' => 'Создание таблицы...',
  'Loading worksheet tabs...' => 'Загрузка вкладок листа...',
  'Reading this form’s fields...' => 'Чтение полей этой формы...',
  'We couldn’t read this form’s fields automatically, so column mapping isn’t available. Don’t worry —<strong>every submitted field will still be synced automatically</strong>, each in its own column, in submission order. The header row is created and kept up to date for you.' => 'Мы не смогли автоматически прочитать поля этой формы, поэтому сопоставление столбцов недоступно. Не волнуйтесь —<strong>каждое отправленное поле по-прежнему будет автоматически синхронизироваться</strong>, каждое в своем столбце, в порядке отправки. Строка заголовка создается и постоянно обновляется.',
  'Drag rows (or use ▲▼) to set the<strong>column order</strong>. Rename any<strong>header</strong>. Turn a field off to skip its column. The letter (A, B, C...) shows where each field lands.' => 'Перетащите строки (или используйте ▲▼), чтобы установить порядок столбцов<strong></strong>. Переименуйте любой заголовок<strong>в</strong>. Отключите поле, чтобы пропустить его столбец. Буква (A, B, C...) показывает, где находится каждое поле.',
  '%dcolumn will be written to the sheet.' . chr(0) . '%dcolumns will be written to the sheet.' => ' Столбец%dбудет записан на лист.' . chr(0) . ' Столбцы%dбудут записаны на лист.' . chr(0) . ' Столбцы%dбудут записаны на лист.',
  'Applying...' => 'Подача заявки...',
  '%dmapped' => '%dсопоставлен',
  'Remove ALL%dbinding? Syncing stops for every form. Your Google Sheets are not deleted.' . chr(0) . 'Remove ALL%dbindings? Syncing stops for every form. Your Google Sheets are not deleted.' => 'Удалить привязку ALL%d? Синхронизация останавливается для каждой формы. Ваши Google Таблицы не удалены.' . chr(0) . 'Удалить ВСЕ привязки%d? Синхронизация останавливается для каждой формы. Ваши Google Таблицы не удалены.' . chr(0) . 'Удалить ВСЕ привязки%d? Синхронизация останавливается для каждой формы. Ваши Google Таблицы не удалены.',
  'Open console.cloud.google.com and log in → click the Project dropdown (top-left) → New Project (or pick an existing one) → enter a name → Create' => 'Откройте console.cloud.google.com и войдите в систему → щелкните раскрывающийся список «Проект» (вверху слева) → «Новый проект» (или выберите существующий) → введите имя → «Создать», «en»]]',
  'APIs & Services → Library → enable<strong>Google Sheets API</strong>and<strong>Google Drive API</strong>(both are required — Drive lists and creates the files)' => 'API и службы → Библиотека → включить<strong>Google Sheets API</strong>и<strong>Google Drive API</strong>(оба обязательны — список дисков и создание файлов)',
  'APIs & Services → Credentials → Create Credentials → Service Account → enter a name → Done' => 'API и службы → Учетные данные → Создать учетные данные → Учетная запись службы → введите имя → Готово',
  'Open the service account → Keys tab → Add Key → Create New Key → choose JSON (file downloads automatically)' => 'Откройте учетную запись службы → вкладка «Ключи» → «Добавить ключ» → «Создать новый ключ» → выберите JSON (файл загружается автоматически)',
  'Form Bindings → pick a form →<strong>Create New Sheet</strong>→ Save. No manual sharing needed — this is the easiest path' => 'Привязки формы → выберите форму →<strong>Создать новый лист</strong>→ Сохранить. Не требуется предоставлять общий доступ вручную — это самый простой путь',
  '...or use an existing sheet' => '...или используйте существующий лист',
  'Prefer your own sheet? Open it → Share → paste the service account email (copy button on its card) → Editor → then Browse My Sheets in the wizard' => 'Предпочитаете свой собственный лист? Откройте его → Поделиться → вставьте адрес электронной почты сервисного аккаунта (кнопка «копировать» на его карточке) → Редактор → затем «Просмотрите мои таблицы» в мастере», \'en\']]',
  'It must be shared with the service account’s email first: open the sheet → Share → paste the email (use the copy button on the connection card) → set Editor → Share. Then click “Browse My Sheets” again.' => 'Сначала его необходимо открыть для электронной почты сервисного аккаунта: откройте лист → Поделиться → вставьте письмо (используйте кнопку копирования на карточке подключения) → установите Редактор → Поделиться. Затем снова нажмите «Просмотреть мои таблицы».',
  'Open Google Cloud Console for the same project → APIs & Services → Library, and enable BOTH “Google Sheets API” and “Google Drive API”. Wait a minute, then retest.' => 'Откройте консоль Google Cloud для того же проекта → API и сервисы → Библиотека и включите ОБА «API Google Таблиц» и «API Google Диска». Подождите минуту, затем повторите тестирование.',
  'Yes. In the binding wizard’s<strong>Columns & Fields</strong>step, drag rows (or use ▲▼) to set the order, rename each column header, and toggle any field off to skip it. The A/B/C badge shows exactly where each field lands.' => 'Да. На шаге<strong>Columns & Fields</strong>мастера привязки перетащите строки (или используйте ▲▼), чтобы установить порядок, переименуйте каждый заголовок столбца и отключите любое поле, чтобы пропустить его. Значок A/B/C показывает, где именно находится каждое поле.',
  'Yes. The<strong>Style & Save</strong>step offers Google-Sheets themes (colored header, frozen top row, alternating row colors). Pick one and it’s applied on the first sync, or click “Apply style now”.' => 'Да. Шаг<strong>«Стиль и сохранение»</strong>предлагает темы Google-Таблиц (цветной заголовок, фиксированный верхний ряд, чередующиеся цвета строк). Выберите один из них, и он будет применен при первой синхронизации, или нажмите «Применить стиль сейчас».',
  'synchronized' => 'синхронизировано',
  '%sis currently unavailable.' => '%sв настоящее время недоступен.',
  'disabled in php.ini:%s' => 'отключено в php.ini:%s',
  'not provided by PHP or its required extension:%s' => 'не предоставляется PHP или его необходимым расширением:%s',
  '%1$scannot run because required PHP functions are unavailable (%2$s). Ask your hosting provider to enable the required PHP extension or remove the listed functions from disabled_functions in php.ini.' => '%1$sне может быть запущен, поскольку необходимые функции PHP недоступны (%2$s). Попросите своего хостинг-провайдера включить необходимое расширение PHP или удалить перечисленные функции из Disabled_functions в php.ini.',
  'Error: server (%s) responded with an invalid request. responded code :%s' => 'Ошибка: сервер (%s) ответил неверным запросом. код ответа:%s',
  'Email delivery failed:%s' => 'Не удалось доставить электронное письмо:%s',
  'Go to the<a href="%s" style="font-weight:600;">Flux Forms Panel</a>' => 'Перейдите на панель<a href="%s" style="font-weight:600;">Flux Forms</a>',
  '%snotification' => ' Уведомление%s',
  'Disabling this feature may affect the proper functionality of Flux Forms. If you plan to use the%sfeature, please ensure it is enabled.' => 'Отключение этой функции может повлиять на правильную работу Flux Forms. Если вы планируете использовать функцию%s, убедитесь, что она включена.',
  'Checked%s' => 'Проверено%s',
  'Checking add-on installation capabilities...' => 'Проверка возможности установки дополнений...',
  'Built with%sYT Form%sby%sWordPress form plugin by whitestudio.team%s' => 'Создано с помощью%sYT Form%sот%sПлагин формы WordPress от whitestudio.team%s',
  'Powered by%1$sYT Form%2$s.%3$sbest Form plugin for Wordpress%4$s.' => 'При поддержке%1$sФорма YT%2$s.%3$sлучший плагин форм для Wordpress%4$s.',
  'Loading forms...' => 'Загрузка форм...',
  'Form:%s(ID:%s)' => 'Форма:%s(ID:%s)',
  'The last delivery check scored%sout of 100. Your messages do leave the site, but most mailboxes will file them as spam, so the people filling in your forms will not see them. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.' => 'Последняя проверка доставки получила оценку%sиз 100. Ваши сообщения покидают сайт, но большинство почтовых ящиков воспринимают их как спам, поэтому люди, заполняющие ваши формы, не увидят их. Это решается отправкой через службу SMTP и добавлением записей SPF и DKIM для вашего домена.',
  'Weekly Flux Forms report for%s' => 'Еженедельный отчет Flux Forms для%s',
  'Here is your weekly snapshot for%s.' => 'Вот ваш еженедельный снимок%s.',
  'Report generated%s' => 'Отчет создан%s',
  'The test email was delivered, but its deliverability score is only%1$sout of 100 (below%2$s), so the emails your forms send are very likely to be rejected or filtered as spam.' => 'Тестовое электронное письмо было доставлено, но его показатель доставляемости составляет только%1$sиз 100 (ниже%2$s), поэтому электронные письма, отправляемые вашими формами, с большой вероятностью будут отклонены или отфильтрованы как спам.',
  'grade%s' => 'оценка%s',
  'Run the email check again until the score is above%s.' => 'Запустите проверку электронной почты еще раз, пока оценка не превысит%s.',
  'You have%1$sforms:%2$sactive and%3$sinactive.' => 'У вас есть формы%1$s:%2$sактивна и%3$sнеактивна.',
  'You can attach up to%1$dfile here. Please wait about%2$dminutes before trying again.' . chr(0) . 'You can attach up to%1$dfiles here. Please wait about%2$dminutes before trying again.' => 'Здесь вы можете прикрепить файл%1$d. Пожалуйста, подождите около%2$dминут, прежде чем повторить попытку.' . chr(0) . 'Здесь вы можете прикрепить до%1$dфайлов. Пожалуйста, подождите около%2$dминут, прежде чем повторить попытку.' . chr(0) . 'Здесь вы можете прикрепить до%1$dфайлов. Пожалуйста, подождите около%2$dминут, прежде чем повторить попытку.',
  'This file is too large. The maximum size for this field is%s.' => 'Этот файл слишком велик. Максимальный размер этого поля —%s.',
  'If your emails are not being delivered, try using an SMTP plugin. For more information,%1$sclick here%2$sor contact our%3$ssupport team%4$s.' => 'Если ваши электронные письма не доставляются, попробуйте использовать плагин SMTP. Для получения дополнительной информации%1$sнажмите здесь%2$sили свяжитесь с нашей службой поддержки%3$s%4$s.',
  'Built with%1$sYT Form%2$sby%3$sWhiteStudio.team%4$s' => 'Создано с помощью%1$sYT Form%2$sот%3$sWhiteStudio.team%4$s',
  'Drag-and-drop form builder: multi-step forms, Stripe payments, conditional logic, dashboard, automations and Flux Certificates integration. Fork based on Easy Form Builder (WhiteStudio, GPL).' => 'Конструктор форм с возможностью перетаскивания: многошаговые формы, платежи Stripe, условная логика, панель мониторинга, автоматизация и интеграция сертификатов Flux. Форк на основе Easy Form Builder (WhiteStudio, GPL).',
  'Keys are set;%dform uses reCAPTCHA.%dforms use reCAPTCHA.' . chr(0) . 'Keys are set;%dform uses reCAPTCHA.%dforms use reCAPTCHA.' => 'Ключи установлены; Форма%dиспользует reCAPTCHA. В формах%dиспользуется reCAPTCHA.' . chr(0) . 'Ключи установлены; Форма%dиспользует reCAPTCHA. В формах%dиспользуется reCAPTCHA.' . chr(0) . 'Ключи установлены; Форма%dиспользует reCAPTCHA. В формах%dиспользуется reCAPTCHA.',
  'Could not connect to Stripe:%s' => 'Не удалось подключиться к Stripe:%s',
  'Stripe API error (HTTP%d).' => 'Ошибка API-интерфейса Stripe (HTTP%d).',
  'field\\x00fields' => 'поле' . chr(0) . 'поля' . chr(0) . 'поля',
  'Flux Donate is not active and the Stripe keys are missing:%dpayment form shows "Online payment is unavailable".\\x00Flux Donate is not active and the Stripe keys are missing:%dpayment forms show "Online payment is unavailable".' => 'Flux Donate не активен и ключи Stripe отсутствуют: форма оплаты%dпоказывает «Онлайн-платеж недоступен».' . chr(0) . 'Flux Donate не активен, а ключи Stripe отсутствуют: в формах оплаты%dотображается сообщение «Онлайн-платеж недоступен».' . chr(0) . 'Flux Donate не активен, а ключи Stripe отсутствуют: в формах оплаты%dотображается сообщение «Онлайн-платеж недоступен».',
  'Not active, but%dactive automation creates or sends certificates; it will fail.\\x00Not active, but%dactive automations create or send certificates; they will fail.' => 'Не активно, но%dактивная автоматизация создает или отправляет сертификаты; это потерпит неудачу.' . chr(0) . 'Не активно, но активные средства автоматизации%dсоздают или отправляют сертификаты; они потерпят неудачу.' . chr(0) . 'Не активно, но активные средства автоматизации%dсоздают или отправляют сертификаты; они потерпят неудачу.',
  '%dautomation is on.\\x00%dautomations are on.' => ' Автоматизация%dвключена.' . chr(0) . ' Автоматизация%dвключена.' . chr(0) . ' Автоматизация%dвключена.',
  '%drun failed in the last 7 days; see the run log.\\x00%druns failed in the last 7 days; see the run log.' => ' За последние 7 дней не удалось выполнить%d; см. журнал запусков.' . chr(0) . ' За последние 7 дней не удалось выполнить%d; см. журнал запусков.' . chr(0) . ' За последние 7 дней не удалось выполнить%d; см. журнал запусков.',
  '%dform has reCAPTCHA on but the site key or secret key is missing; the form is not shown.\\x00%dforms have reCAPTCHA on but the site key or secret key is missing; they are not shown.' => ' В форме%dвключена reCAPTCHA, но отсутствует ключ сайта или секретный ключ; форма не отображается.' . chr(0) . ' В формах%dвключена reCAPTCHA, но отсутствует ключ сайта или секретный ключ; они не показаны.' . chr(0) . ' В формах%dвключена reCAPTCHA, но отсутствует ключ сайта или секретный ключ; они не показаны.',
  'Form\\x00Forms' => 'Форма' . chr(0) . 'Формы' . chr(0) . 'Формы',
  '%dservice account connected\\x00%dservice accounts connected' => 'Учетная запись службы%dподключена' . chr(0) . ' Подключены сервисные учетные записи%d' . chr(0) . ' Подключены сервисные учетные записи%d',
  '%dcolumn will be written to the sheet.\\x00%dcolumns will be written to the sheet.' => ' Столбец%dбудет записан на лист.' . chr(0) . ' Столбцы%dбудут записаны на лист.' . chr(0) . ' Столбцы%dбудут записаны на лист.',
  'Remove ALL%dbinding? Syncing stops for every form. Your Google Sheets are not deleted.\\x00Remove ALL%dbindings? Syncing stops for every form. Your Google Sheets are not deleted.' => 'Удалить привязку ALL%d? Синхронизация останавливается для каждой формы. Ваши Google Таблицы не удалены.' . chr(0) . 'Удалить ВСЕ привязки%d? Синхронизация останавливается для каждой формы. Ваши Google Таблицы не удалены.' . chr(0) . 'Удалить ВСЕ привязки%d? Синхронизация останавливается для каждой формы. Ваши Google Таблицы не удалены.',
  'You can attach up to%1$dfile here. Please wait about%2$dminutes before trying again.\\x00You can attach up to%1$dfiles here. Please wait about%2$dminutes before trying again.' => 'Здесь вы можете прикрепить файл%1$d. Пожалуйста, подождите около%2$dминут, прежде чем повторить попытку.' . chr(0) . 'Здесь вы можете прикрепить до%1$dфайлов. Пожалуйста, подождите около%2$dминут, прежде чем повторить попытку.' . chr(0) . 'Здесь вы можете прикрепить до%1$dфайлов. Пожалуйста, подождите около%2$dминут, прежде чем повторить попытку.',
  'field\\x00fields' . chr(0) . 'field\\x00fields' => 'поле' . chr(0) . 'поля' . chr(0) . 'поля',
